// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Piyasa yapıları ve rekabet (orta).
const ozEconomics7Orta = <(String, String, List<String>, String)>[
  ('Tam rekabet varsayımlarından \'üretim faktörlerinin tam hareketliliği\' neyi sağlar?', 'Kaynakların kârlı alanlara engelsiz kayabilmesini', ['Firmaların hiçbir sabit maliyet taşımadan çalışabilmesini', 'İşçilerin ücret pazarlığı yapmamasını', 'Ürünlerin dış ticarete konu olmamasını'], 'Faktörler serbestçe hareket edebildiğinde emek ve sermaye ekonomik kâr görülen sektörlere akar, zarar eden sektörlerden çıkar; bu da uzun dönem dengesini kurar.'),
  ('Gerçek dünyada tam rekabetin bütün varsayımlarını birlikte sağlayan bir piyasa bulmak neden zordur?', 'Tüm varsayımların aynı anda gerçekleşmesi nadirdir.', ['Tam rekabet çoğu ülkede yasalarla açıkça yasaklanmıştır.', 'Tam rekabette firmalar her zaman zarar eder.', 'Tam rekabet yalnız kamu sektöründe görülür.'], 'Tam rekabet bir kıyaslama modelidir; tarım ve bazı emtia piyasaları ona yaklaşsa da tüm varsayımları aynı anda karşılayan piyasa nadirdir.'),
  ('Tam rekabetteki bir firmada fiyat 12 TL, ortalama değişken maliyet 10 TL, ortalama toplam maliyet 15 TL ve üretim 1.000 birimdir. Firma üretmeye devam ederse zararı kaç TL olur?', '3.000 TL', ['5.000 TL', '2.000 TL', '15.000 TL'], 'Zarar = (ATC − P) × Q = (15 − 12) × 1.000 = 3.000 TL. Kapanırsa sabit maliyet (15 − 10) × 1.000 = 5.000 TL kadar zarar ederdi; bu yüzden üretmek daha iyidir.'),
  ('Tam rekabet sektöründe 100 özdeş firma vardır ve her firmanın arz eğrisi q = 2P\'dir. Sektörün kısa dönem arz eğrisi hangisidir?', 'Q = 200P', ['Q = 2P + 100', 'Q = 102P', 'Q = 50P'], 'Sektör arzı firma arzlarının yatay toplamıdır: 100 × 2P = 200P.'),
  ('Bir sektörde her firmanın arzı q = P − 10 (P ≥ 10) olan 50 özdeş firma vardır; piyasa talebi Q = 1.500 − 50P\'dir. Kısa dönem denge fiyatı kaç TL\'dir?', '20 TL', ['17,50 TL', '25 TL', '30 TL'], 'Sektör arzı 50(P − 10) = 50P − 500. 1.500 − 50P = 50P − 500 ⇒ 100P = 2.000 ⇒ P = 20 TL.'),
  ('Sektör büyüdükçe kullandığı özel girdinin fiyatı yükseliyorsa sektörün uzun dönem arz eğrisi için ne söylenir?', 'Pozitif eğimlidir; artan maliyetli sektördür.', ['Yataydır; sabit maliyetli sektördür.', 'Negatif eğimlidir; azalan maliyetli sektördür.', 'Dikeydir; arz hiç tepki vermez.'], 'Girdi fiyatları sektör genişledikçe yükselirse tüm firmaların maliyet eğrileri yukarı kayar; daha yüksek üretim yalnız daha yüksek fiyatla mümkün olur.'),
  ('Bir sektör büyüdükçe uzmanlaşmış tedarikçiler çoğalıp girdi maliyetleri düşüyorsa uzun dönem arz eğrisinin biçimi hangisidir?', 'Negatif eğimli', ['En düşük maliyet düzeyinde yatay', 'Pozitif eğimli', 'Dikey'], 'Azalan maliyetli sektörde sektörün genişlemesi her firmanın maliyetini düşürür; böylece uzun dönem fiyatı sektör büyüdükçe azalır.'),
  ('Sabit maliyetli bir tam rekabet sektöründe talep kalıcı olarak artarsa uzun dönemde fiyat ve firma sayısı nasıl değişir?', 'Fiyat eski düzeyine döner, firma sayısı artar.', ['Fiyat kalıcı olarak yükselir, firma sayısı değişmez.', 'Fiyat düşer, firma sayısı azalır.', 'Fiyat ve firma sayısı değişmez.'], 'Talep artışı kısa dönemde fiyatı yükseltip kâr yaratır; yeni girişler arzı artırarak fiyatı en düşük ATC\'ye geri çeker. Artan üretimi daha fazla firma karşılar.'),
  ('Tam rekabetteki bir sektörde tüm firmaların sabit maliyetine yeni bir yıllık ruhsat ücreti eklenirse uzun dönemde ne beklenir?', 'Bazı firmalar çıkar ve piyasa fiyatı yükselir.', ['Fiyat değişmez; firmalar ücreti ekonomik kârlarından öder.', 'Firma sayısı artar ve fiyat düşer.', 'Her firmanın üretimi azalır, fiyat düşer.'], 'Ruhsat ücreti ortalama maliyeti yükseltip firmaları zarara sokar; çıkışlar arzı azaltır ve fiyat yeni, daha yüksek en düşük ATC düzeyine çıkar.'),
  ('Tam rekabetteki bir sektörde maliyet düşüren yeni bir teknolojiyi tüm firmalar benimserse uzun dönemde bu kazancın asıl yararlanıcısı kim olur?', 'Tüketiciler, çünkü fiyat yeni düşük maliyete iner.', ['Firmalar, çünkü kalıcı ekonomik kâr elde ederler.', 'Devlet, çünkü vergi gelirleri sürekli artar.', 'Girdi tedarikçileri, çünkü talepleri sürekli artar.'], 'Serbest giriş ve rekabet, maliyet düşüşünü fiyata yansıtır; uzun dönemde firmalar yine normal kâr eder, kazanç düşük fiyat olarak tüketiciye geçer.'),
  ('Bir firmanın ürün fiyatı 60 TL ve talebin fiyat esnekliği mutlak değerce 3\'tür. Marjinal hasılat kaç TL\'dir?', '40 TL', ['22,5 TL', '30 TL', '45 TL'], 'MR = P(1 − 1/|e|) = 60 × (1 − 1/3) = 40 TL.'),
  ('Doğrusal ters talep eğrisi P = a − bQ olan bir tekelin marjinal hasılat eğrisinin eğimi talep eğrisininkine göre nasıldır?', 'İki kat diktir.', ['Talep eğrisiyle aynı eğimdedir.', 'Yarı yarıya daha yatıktır.', 'Yataydır.'], 'TR = aQ − bQ² olduğundan MR = a − 2bQ olur; aynı dikey eksen kesimiyle iki kat eğimlidir ve yatay ekseni talebin yarı noktasında keser.'),
  ('Talebi P = 120 − 3Q olan bir tekel hangi miktarda toplam hasılatını en yükseğe çıkarır?', '20', ['40', '30', '15'], 'MR = 120 − 6Q = 0 ⇒ Q = 20. Toplam hasılat MR\'nin sıfır olduğu noktada en yüksektir.'),
  ('Bir firma fiyatı düşürdüğünde toplam hasılatı azalıyorsa firmanın bulunduğu talep bölgesi için ne söylenir?', 'Talep inelastiktir ve marjinal hasılat negatiftir.', ['Talep esnektir ve marjinal hasılat pozitiftir.', 'Talep birim esnektir ve marjinal hasılat sıfırdır.', 'Talep tam esnektir ve marjinal hasılat fiyata eşittir.'], 'İnelastik bölgede fiyat indirimiyle satılan miktar oransal olarak daha az artar, toplam hasılat düşer; bu da negatif marjinal hasılat demektir.'),
  ('Talebi P = 90 − Q, toplam maliyeti TC = 300 + 10Q olan bir tekelin en yüksek kârı kaç TL\'dir?', '1.300 TL', ['1.600 TL', '1.000 TL', '2.000 TL'], 'MR = 90 − 2Q = 10 ⇒ Q = 40, P = 50. Hasılat 2.000, maliyet 300 + 400 = 700; kâr 1.300 TL.'),
  ('Talebi P = 100 − Q, marjinal maliyeti MC = 2Q olan bir tekelin kârını en yükseğe çıkaran fiyatı kaç TL\'dir?', '75 TL', ['62,50 TL', '60 TL', '80 TL'], 'MR = 100 − 2Q = 2Q ⇒ Q = 25, P = 100 − 25 = 75 TL.'),
  ('Kârını en yüksek yapan bir tekelin fiyatı 50 TL, marjinal maliyeti 30 TL\'dir. Bu noktada talebin fiyat esnekliği mutlak değerce kaçtır?', '2,5', ['1,5', '0,6', '1,67'], 'Ters esneklik kuralı: (P − MC)/P = 1/|e|. (50 − 30)/50 = 0,4 ⇒ |e| = 2,5.'),
  ('Marjinal maliyeti 24 TL olan bir tekelin karşılaştığı talebin esnekliği mutlak değerce 4 ise kârı en yükseğe çıkaran fiyat kaç TL\'dir?', '32 TL', ['30,50 TL', '96 TL', '36 TL'], 'P = MC / (1 − 1/|e|) = 24 / (1 − 0,25) = 24 / 0,75 = 32 TL.'),
  ('Bir ilaç firması patentli bir kanser ilacına çok yüksek, patentli bir ağrı kesiciye görece düşük kâr marjı uygulamaktadır. Ters esneklik kuralına göre en olası açıklama hangisidir?', 'Kanser ilacının talebi ağrı kesicininkinden daha az esnektir.', ['Kanser ilacının marjinal üretim maliyeti neredeyse sıfıra inmiştir.', 'Ağrı kesicinin patenti daha uzun sürelidir.', 'Kanser ilacı tam rekabet piyasasında satılır.'], 'Yakın ikamesi bulunmayan hayati ilaçlarda talep inelastiktir; ağrı kesicilerin birçok ikamesi vardır. Esnekliği düşük üründe marj yüksek olur.'),
  ('Talebin fiyat esnekliği mutlak değerce 1,25 olan bir ürünü satan tekelin fiyat içindeki kâr marjı payı (P − MC)/P yüzde kaçtır?', '%80', ['%25', '%20', '%125'], '(P − MC)/P = 1/1,25 = 0,8, yani fiyatın %80\'i marjinal maliyetin üzerindeki kısımdır.'),
  ('Talebi P = 100 − Q ve marjinal maliyeti sabit 20 TL olan bir tekelin yol açtığı ölü ağırlık kaybı kaç TL\'dir?', '800 TL', ['1.600 TL', '400 TL', '3.200 TL'], 'Tekel: MR = 100 − 2Q = 20 ⇒ Q = 40, P = 60. Rekabet: P = 20 ⇒ Q = 80. Kayıp = ½ × (60 − 20) × (80 − 40) = 800 TL.'),
  ('Talebi P = 100 − Q ve marjinal maliyeti sabit 20 TL olan bir tekel piyasasında tüketici rantı kaç TL\'dir?', '800 TL', ['1.600 TL', '3.200 TL', '400 TL'], 'Tekel Q = 40 ve P = 60 seçer. Tüketici rantı = ½ × (100 − 60) × 40 = 800 TL.'),
  ('Rekabetçi bir piyasa tekele dönüştüğünde tüketici rantının bir kısmı tekelin kârına aktarılır. Toplumsal refah açısından bu aktarım için ne söylenir?', 'Bir el değiştirmedir; asıl net kayıp üretilmeyen birimlerden doğar.', ['Aktarılan tutarın tamamı toplum açısından net bir refah kaybıdır.', 'Aktarım toplam refahı artırır.', 'Aktarım üretici rantını azaltır.'], 'Fiyat artışıyla tüketiciden tekele geçen dikdörtgen bir yeniden dağılımdır; toplam rant içinde kaybolmaz. Net kayıp, yapılmayan alışverişlerin üçgenidir.'),
  ('Talebi P = 100 − Q ve marjinal maliyeti 20 TL olan bir tekele birim başına 10 TL vergi konuyor. Tekelin fiyatı kaç TL artar?', '5 TL', ['10 TL', '20 TL', '2,5 TL'], 'Vergi öncesi MR = 100 − 2Q = 20 ⇒ Q = 40, P = 60. Sonrası MR = 30 ⇒ Q = 35, P = 65. Fiyat 5 TL artar.'),
  ('Tekelin kâr vergisi (ekonomik kârın belirli bir yüzdesi) ödemek zorunda kalması üretim kararını nasıl etkiler?', 'Etkilemez; kârı en yüksek yapan miktar aynı kalır.', ['Üretimi azaltıp fiyatı artırarak vergiyi tüketiciye aktarır.', 'Üretimi rekabetçi düzeye çıkarır.', 'Firmanın piyasadan hemen çıkmasına yol açar.'], 'Kârın sabit bir oranını almak, kârı en yüksek yapan noktayı değiştirmez; vergi sonrası kâr da aynı miktarda en yüksektir.'),
  ('Tekel için neden tam rekabetteki gibi bir arz eğrisi tanımlanamaz?', 'Fiyat ile arz edilen miktar arasında tek ve kalıcı bir eşleşme yoktur.', ['Tekelin marjinal maliyet eğrisi hiçbir koşulda tanımlanamaz.', 'Tekel her zaman sabit miktar üretir.', 'Tekelin üretim kararı yalnız devlet tarafından verilir.'], 'Tekel fiyatı veri almaz, talep eğrisine bakarak hem fiyatı hem miktarı seçer. Talebin biçimi değişince aynı miktara farklı fiyat karşılık gelebilir.'),
  ('İki fabrikalı bir tekelde fabrika 1\'in marjinal maliyeti MC1 = 2Q1, fabrika 2\'ninki MC2 = Q2\'dir. Toplam 30 birim üretilecekse fabrika 1 kaç birim üretmelidir?', '10', ['7,5', '20', '5'], 'MC1 = MC2 ⇒ 2Q1 = Q2 ve Q1 + Q2 = 30. Buradan Q1 = 10, Q2 = 20 bulunur.'),
  ('Aşağıdakilerden hangisi yerleşik firmanın bilinçli olarak yarattığı stratejik bir giriş engelidir?', 'Rakip girerse kullanmak üzere atıl üretim kapasitesi tutmak', ['Sektörün doğası gereği yüksek sabit maliyet gerektirmesi', 'Ürünün yalnızca belirli bir bölgede bulunan hammaddeye dayanması', 'Talebin bir firmanın verimli ölçeğine ancak yetmesi'], 'Stratejik engeller yerleşik firmanın davranışıyla yaratılır; fazla kapasite, girene karşı fiyat savaşı tehdidini inandırıcı kılar. Diğerleri yapısal etkenlerdir.'),
  ('Bir doğal tekelde düzenleyici kurum fiyatı ortalama toplam maliyete eşitlemeyi zorunlu kılarsa hangi sonuç ortaya çıkar?', 'Firma normal kâr eder ama üretim etkin düzeyin biraz altında kalır.', ['Firma zarar eder ve kamunun sübvansiyon vermesi gerekir.', 'Firma tekel kârını korur.', 'Üretim tam olarak P = MC düzeyine ulaşır.'], 'Ortalama maliyet fiyatlamasında P = ATC olduğu için ekonomik kâr sıfırdır; ancak doğal tekelde ATC > MC olduğundan fiyat marjinal maliyetin üzerinde kalır ve küçük bir refah kaybı sürer.'),
  ('Birleşik Krallık\'ta özelleştirilen kamu hizmetlerinde uygulanan \'RPI − X\' formülü hangi düzenleme türünü anlatır?', 'Tavan fiyat düzenlemesi', ['Getiri oranı düzenlemesi', 'Fiyat tabanı uygulaması', 'Kâr payı vergisi'], 'RPI − X yönteminde fiyatların enflasyon oranından X kadar az artmasına izin verilir; firma maliyetini bundan hızlı düşürürse aradaki farkı kâr olarak tutar.'),
  ('Tavan fiyat (price cap) düzenlemesinin getiri oranı düzenlemesine göre en önemli üstünlüğü nedir?', 'Firmaya maliyet düşürme güdüsü vermesi', ['Firmanın hiçbir zaman zarar etmemesini güvence altına alması', 'Firmanın kârını sermayesine bağlaması', 'Fiyatların hiç değişmemesini sağlaması'], 'Fiyat sabitlendiğinde maliyet tasarrufu firmanın kârına kalır; getiri oranı düzenlemesinde ise maliyet düşüşleri fiyata yansıtıldığı için bu güdü zayıftır.'),
  ('Doğal tekeller için düzenlemenin yanı sıra önerilen \'piyasa için rekabet\' yaklaşımı (Demsetz) neyi önerir?', 'İşletme hakkını en iyi fiyatı öneren firmaya ihaleyle vermeyi', ['Piyasayı yasa yoluyla birçok küçük ve bağımsız firmaya bölmeyi', 'Fiyatları tümüyle serbest bırakmayı', 'Firmanın tüm kârını vergilemeyi'], 'Harold Demsetz\'e göre piyasada tek firma kalsa bile, imtiyaz hakkı için yapılan rekabetçi ihale fiyatı maliyete yaklaştırabilir.'),
  ('Bir doğal tekelin marjinal maliyete eşit fiyat koyduğunda uğradığı zararın kapatılması için önerilen yöntemlerden biri hangisidir?', 'Sabit abonelik ücreti ile MC\'ye eşit birim fiyatı birleştirmek', ['Fiyatı yeniden tekel fiyatına yükseltip kâr yaratmak', 'Üretimi yarıya indirmek', 'Firmayı küçük parçalara ayırmak'], 'Sabit abonelik ücreti sabit maliyeti karşılar, birim fiyat ise marjinal maliyete eşit tutulduğu için tüketim etkin düzeyde kalır.'),
  ('Elektrik dağıtımında şebekenin ayrılıp üretim ve perakende satışın rekabete açılması hangi düzenleme anlayışına dayanır?', 'Doğal tekel niteliğindeki şebekeyi, rekabete uygun faaliyetlerden ayırmak', ['Bütün elektrik zincirini yeniden tek bir kamu tekelinin elinde toplamak', 'Elektrik fiyatlarını tümüyle serbest bırakmak', 'Elektrik üretimini yasaklamak'], 'Şebeke gibi kopyalanması verimsiz kısımlar düzenlenen tekel olarak kalırken üretim ve perakende gibi faaliyetlerde çok firmalı rekabet sağlanabilir.'),
  ('Bir ilaç firması aynı ilacı yoksul ülkelerde ucuza, zengin ülkelerde pahalıya satıyor; ucuz ilaçların zengin ülkelere geri ithal edilmesi bu stratejiyi neden tehdit eder?', 'Arbitraj fiyat farkını ortadan kaldırma eğilimindedir.', ['İlacın birim üretim maliyetini yaklaşık iki katına çıkarır.', 'Zengin ülkelerde talebi tam esnek hâle getirir.', 'Firmayı fiyat alıcı yapar.'], 'Paralel ithalat, düşük fiyatlı pazardan alınan malın yüksek fiyatlı pazarda satılmasıdır; pazarlar ayrılamazsa üçüncü derece farklılaştırma sürdürülemez.'),
  ('Bir havayolunun aynı uçuşa \'ekonomi\' ve \'esnek\' adıyla farklı koşullu biletler sunup yolcuların kendi seçimine bırakması hangi mantığa dayanır?', 'Kendi kendini seçme', ['Birinci derece fiyat farklılaştırması', 'Maliyet artı fiyatlama', 'Yıkıcı fiyatlama'], 'İkinci derece farklılaştırmada firma alıcıları tanımaz; farklı paketler sunar ve yüksek ödeme isteği olan alıcıların kendiliğinden pahalı paketi seçmesini sağlar.'),
  ('Bir yayınevinin bir romanı önce ciltli ve pahalı, bir yıl sonra karton kapaklı ve ucuz olarak piyasaya sürmesinin ekonomik amacı nedir?', 'Sabırsız okurlarla bekleyebilen okurları ayırmak', ['Kâğıt ve baskı maliyetlerini ilk yıl içinde tümüyle karşılamak', 'Rakip yayınevlerini piyasadan silmek', 'Ciltli kitabın talebini tam esnek yapmak'], 'Kitabı hemen okumak isteyenlerin ödeme isteği yüksektir. Zamanlamaya dayalı bu sürümleme, alıcıları kendi seçimleriyle gruplara ayırır.'),
  ('Bir tekel iki ayrı pazarda satış yapıyor; marjinal maliyet sabit 10 TL. Birinci pazarda talep esnekliği mutlak değerce 2, ikincide 3\'tür. Pazarlardaki fiyatlar kaç TL olur?', '20 TL ve 15 TL', ['15 TL ve 20 TL', '20 TL ve 30 TL', '12,5 TL ve 10 TL'], 'Her pazarda P = MC/(1 − 1/|e|). Birinci: 10/0,5 = 20 TL; ikinci: 10/(2/3) = 15 TL.'),
  ('Bir tekelin marjinal maliyeti sabit 20 TL\'dir. A pazarında talep P = 100 − Q, B pazarında P = 60 − Q\'dur. Farklılaştırma yapan tekel B pazarında hangi fiyatı koyar?', '40 TL', ['60 TL', '30 TL', '42,50 TL'], 'B pazarında MR = 60 − 2Q = 20 ⇒ Q = 20, P = 40 TL. A pazarında ise Q = 40, P = 60 TL olur.'),
  ('Bir müze yerli turistlere 50 TL, yabancı turistlere 200 TL bilet fiyatı uyguluyor. Fiyat farklılaştırması kuramına göre bu uygulama neyi varsayar?', 'Yabancı turistlerin talebinin daha az esnek olduğunu', ['Yabancılara hizmet vermenin maliyetinin dört kat olduğunu', 'Yerli turistlerin talebinin tam inelastik olduğunu', 'Müzenin tam rekabet piyasasında olduğunu'], 'Yabancı ziyaretçi için müze bilet fiyatı, toplam seyahat harcaması içinde küçük bir paydır; talepleri daha az esnektir ve onlara daha yüksek fiyat uygulanır.'),
  ('Üçüncü derece fiyat farklılaştırmasının toplam refahı artırabileceği durum hangisidir?', 'Tek fiyatla hiç hizmet alamayacak bir grubun düşük fiyatla piyasaya katılması', ['Tüm gruplarda satılan toplam miktarın belirgin biçimde azalması', 'Tekelin her gruba aynı fiyatı koyması', 'Tüketici rantının tamamen tekelce alınması'], 'Farklılaştırma sayesinde tek fiyat altında hizmet alamayan bir pazar açılıyorsa toplam üretim artar ve bu artış refah kazancı yaratabilir.'),
  ('Bir çevrimiçi satıcının geçmiş alışveriş verilerine göre her kullanıcıya ayrı bir fiyat göstermesi kuramsal olarak hangi fiyatlamaya yaklaşmaktadır?', 'Birinci derece (kişiye özel) farklılaştırma', ['Tam rekabet fiyatlaması', 'Ortalama maliyet fiyatlaması', 'Zirve yük fiyatlaması'], 'Her alıcıdan ödeme isteğine yakın fiyat almak birinci derece farklılaştırmanın özüdür; büyük veri bu uygulamayı kısmen mümkün kılar.'),
  ('Tüm müşterileri aynı talebe sahip bir tekel iki parçalı tarifeyle kârını en yükseğe çıkarmak istiyor. Birim fiyatı ve giriş ücretini nasıl belirler?', 'Birim fiyatı MC\'ye eşitler, giriş ücretini tüketici rantı kadar koyar.', ['Birim fiyatı tekel fiyatı yapar, giriş ücretini sıfırlar.', 'Birim fiyatı sıfıra indirir, giriş ücretini marjinal maliyete eşitleyerek belirler.', 'Birim fiyatı ortalama maliyete, giriş ücretini sabit maliyete eşitler.'], 'Birim fiyat MC\'de tutulursa tüketici rantı en büyük olur; tekel bu rantın tamamını giriş ücretiyle alır.'),
  ('Yazıcıyı ucuza satıp kartuştan yüksek kâr elde etme stratejisi neden bir tür fiyat farklılaştırması sayılır?', 'Çok baskı yapan kullanıcılar toplamda daha yüksek fiyat öder.', ['Tüm kullanıcılar, kullanım miktarından bağımsız olarak aynı toplam tutarı öder.', 'Kartuşun üretim maliyeti yazıcıdan yüksektir.', 'Yazıcı tam rekabet piyasasında satılır.'], 'Kartuş tüketimi, yazıcıya biçilen değerin bir ölçüsü gibi çalışır; yoğun kullanıcılar daha çok kartuş alarak daha fazla öder.'),
  ('1933\'te Chamberlin\'den bağımsız olarak \'eksik rekabet\' kuramını geliştiren İngiliz iktisatçı kimdir?', 'Joan Robinson', ['Alfred Marshall', 'John Hicks', 'Piero Sraffa'], 'Joan Robinson\'ın \'The Economics of Imperfect Competition\' kitabı, monopson kavramını da ekonomi literatürüne kazandırmıştır.'),
  ('Monopolcü rekabette uzun dönem dengesinde firmanın talep eğrisi ile ortalama maliyet eğrisi arasındaki ilişki nasıldır?', 'Talep eğrisi ortalama maliyet eğrisine teğettir.', ['Talep eğrisi ortalama maliyetin en düşük noktasından geçer.', 'Talep eğrisi ortalama maliyetin tümüyle altındadır.', 'İki eğri birbirine paraleldir.'], 'Serbest giriş kârı sıfırlar; bu, talep (P) ile ATC\'nin yalnızca bir noktada değmesi demektir. Talep negatif eğimli olduğundan teğet nokta ATC\'nin inen kısmındadır.'),
  ('Monopolcü rekabetin etkinsizliğine karşı savunulan temel görüş hangisidir?', 'Atıl kapasite, tüketicilerin ürün çeşitliliğine ödediği bedel olarak görülebilir.', ['Monopolcü rekabette fiyat her durumda marjinal maliyete eşit olur, bu yüzden etkinsizlik yoktur.', 'Monopolcü rekabette firmalar uzun dönemde büyük kâr eder.', 'Monopolcü rekabette reklam hiç yapılmaz.'], 'Ortalama maliyetin en düşük noktasında üretilmemesi bir maliyettir; ama karşılığında tüketiciler çeşitli marka ve tasarım arasından seçim yapabilir.'),
  ('Cournot düopolünde piyasa talebi P = 120 − Q, iki firmanın marjinal maliyeti sıfırdır. Her firmanın denge üretimi kaçtır?', '40', ['60', '30', '20'], 'Firma 1\'in tepki fonksiyonu q1 = (120 − q2)/2. Simetride q = (120 − q)/2 ⇒ q = 40. Toplam 80, fiyat 40 TL.'),
  ('Talebi P = 100 − Q, iki firmanın marjinal maliyeti 10 TL olan Cournot düopolünde denge fiyatı kaç TL\'dir?', '40 TL', ['55 TL', '10 TL', '32,50 TL'], 'Her firma q = (100 − 10)/3 = 30 üretir; toplam 60, fiyat 100 − 60 = 40 TL.'),
  ('Cournot düopolünde bir firmanın marjinal maliyeti düşerse rakibinin denge üretimi nasıl etkilenir?', 'Azalır.', ['Artar.', 'Değişmez.', 'Sıfıra iner ve rakip kesinlikle çıkar.'], 'Maliyeti düşen firma daha çok üretir; miktarlar stratejik ikame olduğundan rakip, tepki fonksiyonu boyunca üretimini azaltır.'),
  ('Cournot modelinde firmalar tek tek kârlarını en yükseltse de ortak kârları tekel kârından neden düşük kalır?', 'Her firma kendi üretiminin rakibin kârını düşürdüğünü hesaba katmaz.', ['Cournot firmalarının marjinal maliyetleri tekelin maliyetinden her zaman yüksektir.', 'Devlet fiyat tavanı koyar.', 'Talep eğrisi tekelde daha diktir.'], 'Bir firmanın ek üretimi fiyatı düşürerek rakibin hasılatını da azaltır. Bu dışsallık göz ardı edildiğinden toplam üretim tekel düzeyini aşar.'),
  ('Özdeş n firmalı bir Cournot oligopolünde talep doğrusal ve marjinal maliyet sabitse, toplam üretim rekabetçi üretimin hangi kesrine eşittir?', 'n/(n + 1)', ['1/n', '1/(n + 1)', '(n − 1)/n'], 'Her firma rekabetçi miktarın 1/(n + 1)\'ini üretir; n firma toplamda n/(n + 1)\'ini üretir. n = 1 için tekel (1/2), n büyüdükçe 1\'e yaklaşır.'),
  ('Cournot oligopolünde firmanın kâr marjı için Lerner endeksi L = s/|e| biçiminde yazılır. Burada s neyi gösterir?', 'Firmanın pazar payını', ['Firmanın sabit maliyetini', 'Satış vergisi oranını', 'Ürünün ikame esnekliğini'], 'Cournot dengesinde (P − MCi)/P = si/|e| olur; büyük pazar payı ve düşük talep esnekliği yüksek marj demektir.'),
  ('Pazar payı %25 olan bir Cournot firmasının karşılaştığı piyasa talep esnekliği mutlak değerce 2 ise firmanın Lerner endeksi kaçtır?', '0,125', ['0,5', '0,25', '0,0625'], 'L = s/|e| = 0,25/2 = 0,125.'),
  ('Bertrand paradoksunun çözümü olarak önerilen yaklaşımlardan biri hangisidir?', 'Firmaların kapasite kısıtının dikkate alınması', ['Firma sayısının artırılması', 'Ürünlerin tümüyle homojenleştirilip markasız satılması', 'Marjinal maliyetin sıfırlanması'], 'Edgeworth\'ün işaret ettiği gibi bir firma tüm talebi karşılayamıyorsa rakip, kalan talebe MC\'nin üzerinde fiyatla satabilir; farklılaştırma ve tekrarlı etkileşim de diğer çözümlerdir.'),
  ('Fiyatla rekabet eden iki firmadan birinin marjinal maliyeti 8 TL, diğerininki 10 TL\'dir (ürünler özdeş). Bertrand dengesinde ne olması beklenir?', 'Düşük maliyetli firma fiyatı 10 TL\'nin hemen altına koyup tüm pazarı alır.', ['İki firma pazarı eşit paylaşır ve fiyat iki maliyetin ortalaması olan 9 TL olur.', 'Fiyat 8 TL olur ve iki firma da zarar eder.', 'Yüksek maliyetli firma pazarın tamamını alır.'], 'Düşük maliyetli firma rakibin maliyetinin hemen altında fiyat koyarak rakibini dışarıda bırakır ve birim başına yaklaşık 2 TL kâr eder.'),
  ('Farklılaştırılmış ürünlerle fiyat rekabeti yapan iki firmada fiyatlar \'stratejik tamamlayıcı\'dır. Bu ne demektir?', 'Rakip fiyatını artırınca firmanın en iyi fiyatı da artar.', ['Rakip fiyat artırınca firma fiyatını düşürür.', 'İki firma ürünlerini birlikte paket olarak satar.', 'Firmalar fiyatlarını her zaman sıfıra indirir.'], 'Fiyat rekabetinde en iyi yanıt eğrileri pozitif eğimlidir: rakip pahalılaşınca firmanın talebi artar ve o da fiyatını yükseltir. Cournot\'da miktarlar ise stratejik ikamedir.'),
  ('Stackelberg modelinde talep P = 120 − Q ve iki firmanın marjinal maliyeti sıfırdır. Lider firmanın üretimi kaçtır?', '60', ['40', '30', '80'], 'İzleyicinin tepkisi q2 = (120 − q1)/2. Lider bunu kâr fonksiyonuna koyar: q1(120 − q1)/2; en yüksek nokta q1 = 60. İzleyici 30 üretir.'),
  ('Stackelberg modelinde liderin büyük bir miktara bağlanmasının neden inandırıcı olması gerekir?', 'Miktar geri alınamazsa izleyici bunu veri alıp kendi üretimini azaltır.', ['İzleyici her durumda liderin fiyatını kopyalar.', 'Devlet liderin üretimini garanti eder.', 'İzleyicinin marjinal maliyeti her durumda liderinkinden daha yüksektir.'], 'İlk hamle avantajı taahhüde dayanır: lider sonradan üretimini değiştirebilseydi izleyici büyük miktar açıklamasını ciddiye almazdı.'),
  ('Talep P = 120 − Q ve marjinal maliyetlerin sıfır olduğu Stackelberg düopolünde piyasa fiyatı kaç TL\'dir?', '30 TL', ['40 TL', '60 TL', '22,50 TL'], 'Lider 60, izleyici 30 üretir; toplam 90 ve fiyat 120 − 90 = 30 TL. Aynı koşullarda Cournot fiyatı 40 TL\'dir.'),
  ('Stackelberg ve Cournot sonuçları karşılaştırıldığında aynı talep ve maliyet koşullarında tüketiciler hangi modelde daha iyi durumdadır?', 'Stackelberg, çünkü toplam üretim daha fazla, fiyat daha düşüktür.', ['Cournot, çünkü iki firma eş zamanlı karar verdiğinden toplam üretim daha fazladır.', 'İkisinde de eşit durumdadırlar.', 'Cournot, çünkü fiyat daha düşüktür.'], 'Liderin agresif üretimi izleyicinin üretimindeki azalmadan büyüktür; toplam üretim artar, fiyat düşer ve tüketici rantı yükselir.'),
  ('Talep P = 100 − Q ve sıfır marjinal maliyetle 25\'er birim kotayla çalışan iki üyeli bir kartelde, bir üye rakip 25\'te kalırken kotasını aşarak kendi kârını en yükseğe çıkarırsa kaç birim üretir?', '37,5', ['50', '25', '30'], 'Hileci firma rakibin 25 birimini veri alır: q = (100 − 25)/2 = 37,5. Fiyat 37,5\'e düşer, hilecinin kârı 1.406,25 TL\'ye çıkar (kartelde 1.250 TL).'),
  ('Bir kartelin üyeleri arasında üretim kotalarını kâr açısından en verimli biçimde dağıtmak için hangi koşul sağlanmalıdır?', 'Tüm üyelerin marjinal maliyetleri eşit olmalıdır.', ['Her üye, büyüklüğünden bağımsız olarak aynı miktarı üretmelidir.', 'Her üyenin ortalama maliyeti eşit olmalıdır.', 'En büyük üye tüm üretimi yapmalıdır.'], 'Kartel çok tesisli bir tekel gibi davranır; ortak maliyetin en düşük olması için üretim, üyelerin MC\'leri eşitlenecek biçimde dağıtılır.'),
  ('Kartel üyeleri için talebin dalgalı olması neden kartelin istikrarını tehdit eder?', 'Satış düşüşünün hile mi talep daralması mı olduğu ayırt edilemez.', ['Dalgalı talep maliyetleri sıfırlar.', 'Dalgalı talepte fiyatlar yasayla sabitlendiği için kartele gerek kalmaz.', 'Dalgalı talep firma sayısını hemen artırır.'], 'Bir üyenin satışları düştüğünde bunun rakibin gizli indiriminden mi talepten mi kaynaklandığı belirsizse yanlış cezalandırmalar ve fiyat savaşları çıkabilir.'),
  ('1924\'te Osram, Philips ve General Electric gibi üreticilerin ampul ömrünü 1.000 saatle sınırlamak üzere kurduğu kartelin adı nedir?', 'Phoebus karteli', ['Achnacarry karteli', 'Rhenish-Westphalian karteli', 'Seven Sisters karteli'], 'Phoebus karteli ampul ömrünü kısaltarak satışları artırmayı amaçlamış ve planlı eskitmenin bilinen ilk örneklerinden biri olarak tarihe geçmiştir.'),
  ('Bir perakendecinin \'Rakipte daha ucuzunu bulursanız farkı öderiz\' garantisi rekabeti neden zayıflatabilir?', 'Rakibin fiyat indirmesinden elde edeceği müşteri kazancını yok eder.', ['Perakendecinin maliyetlerini sıfıra indirir.', 'Tüketicilerin başka mağazalarda fiyat araştırmasını yasal olarak yasaklar.', 'Ürünleri farklılaştırıp tekel yaratır.'], 'En düşük fiyat garantisi, rakip indirim yaptığında müşterilerin otomatik olarak aynı fiyatı almasını sağlar; indirim yapmanın getirisi azalır ve yüksek fiyat korunur.'),
  ('\'En çok kayrılan müşteri\' (MFN) maddesi bir satıcıyı neye bağlar?', 'Başka bir alıcıya daha düşük fiyat verirse bu alıcıya da aynı fiyatı vermeye', ['Tüm müşterilerine aynı ürün kalitesini sunmaya', 'Bir alıcıya satış yapmadan önce rakiplerin fiyat listesini ona açıklamaya', 'Belirli bir miktarın altında satış yapmamaya'], 'MFN maddesi seçici indirimleri pahalı hâle getirir; satıcı tek bir alıcıya indirim yapınca hepsine yapmak zorunda kalır, bu da fiyat rekabetini zayıflatabilir.'),
  ('Rakip firmaların gelecekteki fiyat planlarını ayrıntılı biçimde kamuoyuna duyurması rekabet otoritelerince neden kuşkuyla karşılanır?', 'Örtülü koordinasyona aracılık edebileceği için', ['Tüketicilerin fiyat bilgisini azalttığı için', 'Firmaların maliyetini artırdığı için', 'Vergi gelirini düşürdüğü için'], 'Geleceğe dönük fiyat duyuruları rakiplere sinyal işlevi görüp açık bir anlaşma olmadan uyumlu davranışı kolaylaştırabilir.'),
  ('Bir sektörde ürünlerin çok farklı özelliklerde ve müşteriye özel tekliflerle satılması zımni gizli anlaşmayı nasıl etkiler?', 'Zorlaştırır; çünkü ortak bir fiyat üzerinde uzlaşmak ve hileyi izlemek güçleşir.', ['Kolaylaştırır; çünkü her firmanın kendine ait sadık bir müşteri kitlesi oluşur.', 'Etkilemez; anlaşmalar yalnızca firma sayısına bağlıdır.', 'Kolaylaştırır; çünkü fiyatlar herkesçe bilinir.'], 'Homojen ve şeffaf fiyatlı ürünlerde koordinasyon kolaydır; karmaşık ve gizli tekliflerde ise sapmaları görmek ve cezalandırmak zordur.'),
  ('Baskın firma modelinde piyasa talebi Q = 200 − P, küçük firmaların toplam arzı Qs = P\'dir. Baskın firmanın kalan (artık) talebi hangisidir?', 'Q = 200 − 2P', ['Q = 200 − P', 'Q = 200 + P', 'Q = 100 − P'], 'Kalan talep = piyasa talebi − saçak arzı = (200 − P) − P = 200 − 2P.'),
  ('Baskın firma modelinde küçük (saçak) firmaların arzı artarsa baskın firmanın fiyat gücü nasıl etkilenir?', 'Kalan talebi daralıp daha esnek hâle geldiğinden azalır.', ['Kalan talebi genişleyip daha dik hâle geldiğinden belirgin biçimde artar.', 'Hiç etkilenmez.', 'Baskın firma tam tekel olur.'], 'Saçak ne kadar güçlüyse baskın firmanın kalan talebi o kadar küçük ve fiyata duyarlıdır; bu da baskın firmanın koyabileceği marjı düşürür.'),
  ('İki firma reklam yapıp yapmamaya karar veriyor. İkisi de yaparsa her biri 4, ikisi de yapmazsa 6 milyon TL kâr ediyor. Yalnız biri yaparsa yapan 8, yapmayan 2 milyon kazanıyor. Nash dengesi hangisidir?', 'İkisi de reklam yapar.', ['İkisi de reklam yapmaz.', 'Yalnızca birinci firma reklam yapar.', 'Firmalar her dönem sırayla reklam yapar ve kârı bölüşür.'], 'Rakip ne yaparsa yapsın reklam yapmak daha kârlıdır (8 > 6 ve 4 > 2). Bu baskın strateji iki firmayı da 4\'er milyonla yetinmeye götürür; oysa ikisi de yapmasa 6\'şar kazanırlardı.'),
  ('Bir oyunda hiçbir oyuncunun baskın stratejisi yoksa ama oyunda saf stratejili bir Nash dengesi varsa, bu dengeyi bulmanın yolu nedir?', 'Her oyuncunun en iyi yanıtlarını işaretleyip ortak hücreyi bulmak', ['İki oyuncunun toplam kazancının en yüksek olduğu hücreyi doğrudan seçmek', 'Her oyuncunun en kötü sonucunu en yükseğe çıkarmak', 'Matrisin köşegenindeki hücreleri seçmek'], 'Nash dengesi, iki oyuncunun da birbirine en iyi yanıt verdiği hücredir. En iyi yanıtların kesiştiği hücre(ler) dengeyi verir; toplam kazancın en yüksek olması gerekmez.'),
  ('Bir oyunun Nash dengesinin Pareto etkin olmaması ne anlama gelir?', 'Tüm oyuncuların daha iyi olacağı başka bir sonuç vardır ama denge oraya ulaşmaz.', ['Dengede oyunculardan biri stratejisini tek başına değiştirerek daha çok kazanabilir.', 'Dengede oyuncuların kazancı her zaman sıfırdır.', 'Oyunun hiçbir dengesi yoktur.'], 'Nash dengesinde kimse tek başına sapmak istemez; ancak tutsak ikileminde olduğu gibi herkesin daha iyi olduğu bir sonuç olabilir ve bu bireysel güdülerle sağlanamaz.'),
  ('İki tekerlekli bisiklet üreticisinin hangi şehre fabrika kuracağını seçtiği bir oyunda iki ayrı saf strateji Nash dengesi bulunuyor. Bu durum ne gösterir?', 'Hangi dengenin gerçekleşeceği koordinasyona ya da beklentilere bağlıdır.', ['Oyun çözümsüzdür; birden çok denge olduğu için hiçbir denge gerçekleşemez.', 'Her iki denge aynı anda gerçekleşir.', 'Oyuncuların baskın stratejisi vardır.'], 'Birden fazla Nash dengesi olan koordinasyon oyunlarında sonuç; tarih, sözleşme ya da odak noktaları gibi oyun dışı etkenlerle belirlenir.'),
  ('Tutsak ikilemi bakış açısıyla kartel anlaşmalarını yasaklamanın yanında, rekabet otoritelerinin kartel üyelerine itiraf karşılığı ceza indirimi tanıması ne amaçlar?', 'Üyeler arasında güvensizlik yaratıp anlaşmayı bozmak', ['Kartelin elde ettiği tekel kârını vergi yoluyla devletle paylaşmasını sağlamak', 'Kartelin fiyatlarını yasal hâle getirmek', 'Yeni firmaların kartele katılmasını sağlamak'], 'Pişmanlık programları kartel üyelerini bir tutsak ikilemine sokar: başkası önce itiraf ederse cezayı kendisi yer; bu da itiraf yarışını başlatır.'),
  ('Oyun sonsuz kez tekrarlanırsa tutsak ikileminde iş birliği hangi koşulda sürdürülebilir?', 'Oyuncular geleceğe yeterince değer veriyorsa', ['Oyuncular yalnızca bugünkü kazancı önemsiyor ve geleceği tümüyle iskonto ediyorsa', 'Oyunun son turu herkesçe biliniyorsa', 'Oyunculardan biri baskın stratejiye sahip değilse'], 'Halk teoremi (folk theorem) sonuçlarına göre gelecekteki ceza tehdidi, bugünkü sapma kazancından ağır basıyorsa iş birliği bir denge olabilir.'),
  ('Bir tutsak ikilemi tam 10 kez oynanacak ve bunu iki oyuncu da biliyor. Kuramsal olarak oyunun her turunda ne beklenir?', 'İki oyuncu da her turda sapar.', ['İlk 9 turda iş birliği, son turda sapma olur.', 'Tüm turlarda iş birliği yapılır.', 'Oyuncular sırayla iş birliği yapar.'], 'Son turda gelecek olmadığından sapılır; bu bilindiğinde 9. turda da iş birliğinin ödülü kalmaz. Geriye doğru akıl yürütme tüm turlarda sapmayı verir.'),
  ('Oligopolde firmaların sık ve gözlenebilir etkileşimi (ör. her gün açıklanan fiyatlar) gizli anlaşmayı neden kolaylaştırır?', 'Sapma hemen fark edilip hızla cezalandırılabilir.', ['Sık etkileşim talebi tam inelastik yapar.', 'Her gün fiyat değiştirmek yasalarca yasaklandığı için fiyatlar uzun süre sabit kalır.', 'Firmaların maliyeti her gün düşer.'], 'Tekrarlı oyunlarda sapmanın kazancı, cezanın gelmesine kadar geçen süreye bağlıdır; sık ve şeffaf etkileşim bu süreyi kısaltır.'),
  ('Sıralı bir oyunda yerleşik firma, giriş olursa \'fiyat savaşı açacağını\' söylüyor; ancak giriş olduktan sonra fiyat savaşı kendisine uyum sağlamaktan daha az kâr getirecek. Bu tehdit için ne söylenir?', 'İnanılır değildir; giren firma bunu göz ardı eder.', ['İnanılırdır; çünkü yerleşik firma her zaman büyüktür.', 'İnanılırdır; çünkü tehdit açıkça söylenmiştir.', 'Tehdidin inanılırlığı giren firmayı ilgilendirmez.'], 'Alt oyun yetkin dengede oyuncular, tehdidin uygulanma anında gerçekten en iyi seçim olup olmadığına bakar. Uygulanması kârsız tehdit boş tehdittir.'),
  ('Reinhard Selten\'in tanımladığı \'alt oyun yetkin denge\' kavramı Nash dengesini nasıl iyileştirir?', 'İnanılır olmayan tehditlere dayanan dengeleri eler.', ['Karma stratejileri tümüyle ortadan kaldırıp yalnız saf stratejilere izin verir.', 'Oyunculara bağlayıcı sözleşme imkânı verir.', 'Yalnız sıfır toplamlı oyunlara uygulanır.'], 'Alt oyun yetkinlik, oyunun her alt aşamasında da Nash dengesinin oynanmasını ister; böylece yol dışındaki boş tehditler dengeyi destekleyemez.'),
  ('Bir giriş oyununda yerleşik firma, giriş olmadan önce geri dönüşü olmayan büyük bir kapasite yatırımı yaparsa fiyat savaşı tehdidi nasıl etkilenir?', 'İnanılır hâle gelebilir; kurulu kapasiteyi kullanmak kârlı olur.', ['Tümüyle anlamsız hâle gelir; çünkü yatırım batık olduğu için kararları etkilemez.', 'Giren firmanın maliyetini doğrudan düşürür.', 'Yerleşik firmayı piyasadan çıkarır.'], 'Batık kapasite, giriş sonrası yüksek üretimin marjinal maliyetini düşürür; böylece sert tepki gerçekten en iyi yanıt olur ve tehdit inandırıcılık kazanır.'),
  ('Sıralı bir oyunda ilk hamleyi yapmanın her zaman avantaj sağlamadığına örnek olabilecek durum hangisidir?', 'Fiyatını ilk açıklayan firmanın hemen altından geçilmesi', ['Stackelberg miktar rekabetinde liderin fazla üretmesi', 'Bir firmanın patent alarak pazara ilk girmesi', 'Bir firmanın kapasiteyi önceden kurması'], 'Fiyat rekabetinde fiyatını ilk açıklayan firma, izleyicinin biraz daha düşük fiyatla müşterileri almasına açık hâle gelir; burada ikinci olmak avantajlıdır.'),
  ('Sınır fiyatlaması modeline yöneltilen temel eleştiri nedir?', 'Giriş olduktan sonra düşük fiyatı sürdürmek kârlı olmayabilir.', ['Sınır fiyatı her durumda tekel fiyatından yüksek olduğu için girişi tersine teşvik eder.', 'Sınır fiyatlaması yalnızca tam rekabette uygulanır.', 'Sınır fiyatı yeni girenin maliyetini artırır.'], 'Giriş kararı yerleşik firmanın giriş sonrası davranışına bağlıdır. Bugünkü fiyat bunu bağlamıyorsa rasyonel bir aday firma düşük fiyattan etkilenmez; model ancak bilgi asimetrisiyle anlam kazanır.'),
  ('Yıkıcı fiyatlamanın akılcı bir strateji olabilmesi için kuramsal olarak hangi koşulun sağlanması gerekir?', 'Rakipler çıktıktan sonra fiyatı yükseltip kayıpları telafi etmek', ['Yeni firmaların piyasaya kolayca ve maliyetsiz girebilmesi', 'Firmanın tam rekabet piyasasında olması', 'Tüketicilerin talebinin tam esnek olması'], 'Yıkıcı fiyatlama bugünkü bir kayıptır; ancak rakipler elendikten sonra yüksek fiyatla bu kayıp geri alınabiliyorsa anlamlıdır. Giriş kolaysa telafi mümkün olmaz.'),
  ('Bir firmanın maliyetinin altında satış yapması her zaman yıkıcı fiyatlama sayılmaz. Aşağıdakilerden hangisi meşru bir gerekçe olabilir?', 'Bozulmaya yüz tutmuş stokun eritilmesi', ['Rakibin piyasadan çıkarılması', 'Yeni girenin caydırılması', 'Pazar payının tekel düzeyine çıkarılması'], 'Bayatlayacak ürünlerin tasfiyesi ya da tanıtım indirimleri gibi durumlarda maliyetin altında satış rekabet karşıtı bir amaç taşımaz.'),
  ('HHI değeri 2.500 olan bir piyasa, kaç eşit büyüklükte firmanın oluşturduğu piyasaya denk yoğunluktadır?', '4', ['25', '2,5', '40'], 'Eşit paylı n firmada HHI = 10.000/n. 10.000/2.500 = 4 eşdeğer firma.'),
  ('Pazar payları %30 ve %20 olan iki firma birleşirse sektörün HHI değeri kaç puan artar?', '1.200', ['500', '600', '2.500'], 'Birleşme öncesi katkı 900 + 400 = 1.300; sonrası 50² = 2.500. Artış 2 × 30 × 20 = 1.200 puandır.'),
  ('İki sektörün CR4 değeri aynı %80\'dir. A sektöründe paylar 20-20-20-20, B\'de 65-5-5-5\'tir. Hangi yorum doğrudur?', 'B sektörünün HHI\'si daha yüksektir ve tek firma hâkimiyeti daha olasıdır.', ['İki sektörün yoğunlaşma düzeyleri ve rekabet koşulları hiçbir farkla tıpatıp aynıdır.', 'A sektörünün HHI\'si daha yüksektir.', 'Bu verilerle HHI hakkında yorum yapılamaz.'], 'CR4 aynı olsa da B\'de tek firma pazarın üçte ikisine sahiptir; HHI bu eşitsizliği yakalar (B\'de 4.300\'ü aşar, A\'da 1.600 civarındadır).'),
  ('Yoğunlaşma ölçülerinin piyasa gücünü yanıltıcı biçimde gösterebileceği durum hangisidir?', 'Piyasa çok dar ya da çok geniş tanımlandığında', ['Firmaların pazar payları biliniyorsa', 'Firma sayısı ikiden fazlaysa', 'Ürünler homojense'], 'Yoğunlaşma, ilgili pazarın nasıl tanımlandığına bağlıdır; yerel bir pazarı ulusal sayan ya da ithalatı göz ardı eden tanımlar sonuçları çarpıtır.'),
  ('Kârını en yükseğe çıkaran bir tekelin karşılaştığı talep esnekliği mutlak değerce 5 ise Lerner endeksi kaçtır?', '0,2', ['5', '0,5', '0,8'], 'Kâr maksimizasyonunda L = 1/|e| = 1/5 = 0,2.'),
  ('Yüksek bir Lerner endeksinin her zaman yüksek ekonomik kâr anlamına gelmemesinin nedeni nedir?', 'Yüksek sabit maliyetler marjı tümüyle tüketebilir.', ['Lerner endeksi tam rekabet piyasalarında her zaman 1 değerini aldığı için yanıltıcıdır.', 'Lerner endeksi talep esnekliğinden bağımsızdır.', 'Lerner endeksi yalnızca toplam hasılatı ölçer.'], 'Lerner endeksi marjinal maliyete göre marjı ölçer; yazılım ya da ilaç gibi yüksek sabit maliyetli sektörlerde büyük marj, yalnızca Ar-Ge maliyetini karşılıyor olabilir.'),
  ('Rekabet hukukunda ilgili ürün pazarını belirlemede kullanılan SSNIP testi neyi sınar?', 'Varsayımsal tekelin küçük ama kalıcı bir zammı kârlı yapıp yapamayacağını', ['Pazardaki firmaların ödenmemiş vergi borçlarının ve teşviklerinin toplam tutarını', 'Ürünün ihracat payının ne olduğunu', 'Firmaların sabit maliyetlerinin büyüklüğünü'], 'SSNIP (küçük ama anlamlı ve geçici olmayan fiyat artışı) testinde tüketiciler başka ürünlere kayıp artışı kârsız kılıyorsa o ürünler de pazara eklenir.'),
  ('SSNIP testine göre bir maden suyu markasının fiyatı %10 artınca tüketicilerin çoğu gazlı içeceklere geçiyorsa ne sonuca varılır?', 'Gazlı içecekler de aynı ilgili ürün pazarına dahil edilmelidir.', ['Maden suyu ayrı ve bağımsız bir pazardır.', 'Fiyat artışı varsayımsal tekel için kârlıdır.', 'Gazlı içecekler maden suyunun tamamlayıcısıdır.'], 'Artış, ikameye kayış nedeniyle kârsız oluyorsa pazar tanımı genişletilir; gazlı içecekler maden suyuyla aynı rekabet kısıtını oluşturur.'),
  ('Çimento gibi ağır ve ucuz bir ürünün ilgili coğrafi pazarının genellikle dar (bölgesel) tanımlanmasının nedeni nedir?', 'Taşıma maliyetinin ürün değerine göre yüksek olması', ['Çimentonun hiçbir ikamesinin bulunmaması', 'Çimento üretiminin yasal tekel olması', 'Çimento talebinin tam esnek olması'], 'Uzak bölgelerden gelen çimento yüksek nakliye maliyeti taşıdığından yerel fiyatları etkileyemez; bu da pazarı bölgesel hâle getirir.'),
  ('Endüstriyel iktisatta Edward Mason ve Joe Bain\'e dayanan \'yapı-davranış-performans\' yaklaşımı neyi öne sürer?', 'Yapının davranışı, davranışın da performansı belirlediğini', ['Firma performansının piyasa yapısını ve davranışını hiçbir biçimde etkilemediğini', 'Devletin fiyatları belirlemesi gerektiğini', 'Piyasa yapısının yalnızca vergilerle belirlendiğini'], 'Bu paradigmada yoğunlaşma ve giriş engelleri gibi yapı unsurları fiyatlama ve reklam gibi davranışları, bunlar da kârlılık ve etkinliği belirler.'),
  ('Türkiye\'de rekabet hukukunu düzenleyen 4054 sayılı Kanun hangi yıl kabul edilmiştir?', '1994', ['1984', '2001', '1997'], '4054 sayılı Rekabetin Korunması Hakkında Kanun 7 Aralık 1994\'te kabul edilmiştir; Rekabet Kurumu ise fiilen 1997\'de çalışmaya başlamıştır.'),
  ('4054 sayılı Kanun\'a göre rekabeti kısıtlayan bir anlaşma, tüketiciye yarar sağlayan yeni gelişmeler ya da ekonomik iyileşmeler doğuruyorsa ve diğer koşulları da taşıyorsa Kurul ne verebilir?', 'Muafiyet', ['Hâkim durum belgesi', 'İhracat teşviki', 'Patent hakkı'], 'Kanunun 5. maddesine göre belirli koşulları sağlayan anlaşmalar, rekabeti kısıtlasalar da yasak kapsamından muaf tutulabilir.'),
  ('Rekabet hukukunda kartel anlaşmaları için uygulanan \'kendiliğinden yasak\' (per se) kuralı ne anlama gelir?', 'Anlaşmanın etkilerine bakılmadan doğrudan hukuka aykırı sayılması', ['Anlaşmanın yalnızca tüketici zararı somut olarak kanıtlanırsa yasaklanabilmesi', 'Anlaşmanın her durumda muaf tutulması', 'Anlaşmanın yalnız ihracatta geçerli olması'], 'Fiyat tespiti ve pazar paylaşımı gibi ağır ihlaller per se yasaktır; diğer uygulamalar ise \'makul olma kuralı\' (rule of reason) ile olumlu ve olumsuz etkileri tartılarak incelenir.'),
  ('ABD\'de 1914\'te çıkarılan ve rekabeti önemli ölçüde azaltan birleşmeleri, bazı fiyat ayrımcılığı ve bağlama uygulamalarını yasaklayan yasa hangisidir?', 'Clayton Yasası', ['Sherman Yasası', 'Robinson-Patman Yasası', 'Glass-Steagall Yasası'], 'Clayton Yasası, Sherman Yasası\'nın genel hükümlerini belirli uygulamalara yönelik ayrıntılı yasaklarla tamamlamıştır.'),
  ('Sherman Yasası\'nın 2. bölümü hangi davranışı hedef alır?', 'Tekelleştirmeyi ya da tekelleştirmeye teşebbüsü', ['Rakip firmalar arasında yapılan fiyat tespiti anlaşmalarını', 'İthalat kotalarını', 'İşçi sendikalarını kurmayı'], 'Sherman Yasası\'nın 1. bölümü ticareti kısıtlayan anlaşmaları, 2. bölümü ise tekelleştirme ve tekelleştirmeye teşebbüsü yasaklar.'),
  ('1911 Standard Oil kararında ABD Yüksek Mahkemesi\'nin benimsediği ve her ticaret kısıtlamasının değil yalnız \'makul olmayanların\' yasak olduğunu öngören ilke hangisidir?', 'Makul olma kuralı (rule of reason)', ['Kendiliğinden yasak kuralı (per se rule)', 'Areeda-Turner kuralı', 'Temel tesis doktrini'], 'Mahkeme Sherman Yasası\'nı yorumlarken makul olma kuralını benimsemiş; böylece kısıtlamanın etkileri tek tek değerlendirilmeye başlanmıştır.'),
  ('Rekabet hukukunda \'temel tesis\' (essential facility) doktrini neyi öngörür?', 'Rakiplerin vazgeçilmez altyapıya makul koşullarla erişmesini', ['Her firmanın kendi altyapısını sıfırdan kurmak zorunda tutulmasını', 'Temel tesislerin yalnızca devletçe işletilmesini', 'Altyapı sahibinin tüm rakipleri dışlayabilmesini'], 'Bir hâkim firma, rakiplerin faaliyeti için kopyalanması olanaksız bir tesise (ör. liman, şebeke) sahipse erişimi haksız biçimde reddetmesi kötüye kullanma sayılabilir.'),
  ('Birleşme denetiminde \'başarısız firma savunması\' neyi ileri sürer?', 'Hedef firmanın birleşme olmadan da batacağını', ['Birleşen firmaların ikisinin de pazar payının çok küçük olduğunu', 'Birleşmenin ihracatı artıracağını', 'Birleşmenin vergi gelirini yükselteceğini'], 'Hedef firma birleşme olmadan da batacak ve varlıkları piyasada kalmayacaksa, birleşme rekabeti mevcut duruma göre daha fazla azaltmaz; bu durumda izin verilebilir.'),
  ('Bir birleşmenin rekabet otoritesi tarafından koşullu olarak onaylanması için birleşen firmalardan bir fabrikayı ya da markayı satmaları istenmesine ne ad verilir?', 'Yapısal çözüm', ['Davranışsal çözüm', 'Pişmanlık (leniency) başvurusu', 'Muafiyet'], 'Yapısal çözümlerde rekabet sorununu gidermek için varlık satışı istenir; davranışsal çözümler ise fiyat ya da erişim taahhütleri gibi davranış kısıtlarıdır.'),
  ('Birleşme analizinde \'tek taraflı etki\' neyi anlatır?', 'Birleşen firmanın koordinasyon olmadan tek başına zam yapabilmesi', ['Birleşmeden sonra piyasadaki tüm firmaların açıkça bir kartel kurması', 'Birleşmenin yalnız tek bir ülkeyi etkilemesi', 'Birleşen firmalardan birinin piyasadan çıkması'], 'Yakın ikame ürünler aynı çatı altına girince, birinin fiyatı artınca kaçan müşteriler diğer ürüne gidecektir; firma bu yüzden fiyat artırmayı kârlı bulabilir.'),
  ('Birleşme analizinde \'koordineli etki\' kaygısı neyi ifade eder?', 'Kalan firmaların örtülü gizli anlaşmaya girmesinin kolaylaşması', ['Birleşen firmaların iş gücünü ve yönetim kadrolarını tek çatıda toplaması', 'Birleşmenin ihracatı artırması', 'Birleşmenin sabit maliyetleri azaltması'], 'Firma sayısı azalınca ve piyasa daha simetrik hâle gelince örtülü koordinasyon kolaylaşabilir; rekabet otoriteleri bu riski de inceler.'),
  ('Çifte marjinalleşme sorununu çözmek için üretici ile perakendeci arasında kullanılabilecek sözleşme türü hangisidir?', 'Toptan fiyatı MC\'ye eşitleyip sabit bayilik ücreti almak', ['Toptan fiyatı tekel fiyatının iki katına çıkarmak', 'Perakendeciye hiçbir münhasırlık vermeden, pazarlıksız liste fiyatından satmak', 'Perakende fiyatı en düşük düzeyde tutmayı yasaklamak'], 'İki parçalı bir sözleşmede toptan fiyat MC\'ye çekilir, böylece perakendeci bütünleşik firmanın fiyatını koyar; üretici kârını sabit ücretle alır.'),
  ('Üreticilerin asgari perakende fiyatı belirlemesini savunanların ileri sürdüğü \'beleşçilik (free-riding)\' gerekçesi nedir?', 'Hizmet veren bayiyi, hizmet vermeyen ucuz bayiye karşı korumak', ['Bayilerin vergi ödemelerini kolaylaştırıp kayıt dışılığı azaltmak', 'Tüketicilerin daha düşük fiyattan almasını sağlamak', 'Ürün çeşitliliğini azaltmak'], 'Müşteri pahalı bayide bilgi alıp ucuz bayiden satın alırsa hizmet sunmanın getirisi kalmaz; asgari fiyat bu dışsallığı önleyebilir.'),
  ('Dikey bütünleşmenin rekabet açısından yaratabileceği temel risk hangisidir?', 'Girdi ya da müşteri erişimini kapatıp rakipleri dışlama', ['Çifte marjinalleşmeyi artırarak fiyatları yükseltme', 'İşlem maliyetlerini yükseltme', 'Ürün çeşitliliğini zorunlu olarak artırma'], 'Bütünleşik firma, rakiplerine girdi satmayı reddedebilir ya da pahalılaştırabilir; bu \'piyasa kapama\' etkisi rekabeti zayıflatabilir.'),
  ('Bir faks makinesi tek başına işe yaramazken, faks sahibi sayısı arttıkça her bir makinenin değeri artar. Bu durum hangi tür ağ dışsallığıdır?', 'Doğrudan ağ dışsallığı', ['Dolaylı (tamamlayıcı ürün) ağ dışsallığı', 'Negatif dışsallık', 'Ölçek eksi ekonomisi'], 'Doğrudan ağ dışsallığında kullanıcılar birbirleriyle doğrudan etkileşir; telefon ve faks klasik örneklerdir.'),
  ('Bir oyun konsolunu alan kişi sayısı arttıkça o konsol için daha çok oyun yazılması ve bunun konsolun değerini artırması hangi tür ağ etkisidir?', 'Dolaylı ağ dışsallığı', ['Doğrudan ağ dışsallığı', 'Negatif tüketim dışsallığı', 'Kapsam ekonomisi'], 'Dolaylı ağ etkisinde kullanıcı sayısı tamamlayıcı ürünlerin (oyunlar, uygulamalar) arzını artırır; değer bu yolla dolaylı olarak yükselir.'),
  ('Paul David\'in QWERTY klavye örneği iktisatta hangi kavramı açıklamak için kullanılır?', 'Patika bağımlılığı', ['Kapsam ekonomisi', 'Ölçek eksi ekonomisi', 'Ters esneklik kuralı'], 'David\'e göre tarihsel tesadüfler ve ağ etkileri, daha iyi alternatifler çıksa bile bir standardın kalıcı olmasına yol açabilir.'),
  ('Geçiş maliyetlerinin yüksek olduğu piyasalarda firmaların ilk dönemde fiyatları çok düşük tutmasının mantığı nedir?', 'Müşteri kazanıp sonra kilitlenmeden yararlanmak', ['Ürünün maliyetinin ilk dönemde sıfır olması', 'Yasaların ilk dönemde yüksek fiyat uygulanmasını kesin olarak yasaklaması', 'Talebin ilk dönemde tam inelastik olması'], 'Bu \'önce yatırım, sonra hasat\' (bargains-then-ripoffs) örüntüsünde firma müşteri tabanı kurmak için zarar eder, kilitlenen müşteriden sonra kazanır.'),
  ('Ağ dışsallıklarının güçlü olduğu bir piyasada daha iyi bir teknolojinin pazara girmesini zorlaştıran temel sorun nedir?', 'Kullanıcıların ötekiler geçmedikçe geçmek istememesi', ['Yeni teknolojinin daha pahalı olmasının yasal zorunluluk olması', 'Yeni teknolojinin hiç patent alamaması', 'Eski teknolojinin hiç kullanıcısının olmaması'], 'Her kullanıcı için yeni ağın değeri, oraya geçecek diğer kullanıcılara bağlıdır; bu koordinasyon sorunu \'aşırı eylemsizlik\' (excess inertia) olarak bilinir.'),
  ('Bir gece kulübünün kadınlara ücretsiz giriş, erkeklere ücretli giriş uygulaması iki taraflı piyasa kuramıyla nasıl açıklanır?', 'Bir tarafı sübvanse edip diğer tarafı çekmek', ['Kadınlara hizmet vermenin kulübe hiçbir ek maliyet getirmemesi', 'Erkeklerin talebinin tam esnek olması', 'Kulübün tam rekabet piyasasında olması'], 'İki taraflı platformlar, varlığı diğer taraf için değerli olan grubu düşük fiyatla çeker ve kârı diğer taraftan elde eder.'),
  ('Jean-Charles Rochet ile birlikte iki taraflı piyasalar kuramını geliştiren ve 2014 Nobel Ekonomi Ödülü\'nü piyasa gücü ve düzenleme analizi için alan iktisatçı kimdir?', 'Jean Tirole', ['Oliver Hart', 'Paul Krugman', 'William Nordhaus'], 'Jean Tirole, 2014\'te \'piyasa gücü ve düzenleme analizi\' nedeniyle Nobel Ekonomi Ödülü\'nü almıştır; Rochet ile iki taraflı piyasalar üzerine öncü çalışmalar yapmıştır.'),
  ('Bir kullanıcının aynı anda birden fazla rakip platformu (ör. iki farklı yemek siparişi uygulaması) kullanmasına ne ad verilir?', 'Çoklu bağlanma (multi-homing)', ['Kilitlenme', 'Tekli bağlanma (single-homing)', 'Bağlama satışı'], 'Çoklu bağlanma yaygınsa tek bir platformun kullanıcıları kilitlemesi zorlaşır; bu da platformlar arası rekabeti canlı tutar.'),
  ('Emek arzı w = 10 + L olan bir monopsonda toplam ücret maliyeti w·L = 10L + L²\'dir. Marjinal faktör maliyeti hangisidir?', 'MFC = 10 + 2L', ['MFC = 10 + L', 'MFC = 10', 'MFC = 10L + 2'], 'Toplam maliyetin L\'ye göre türevi alınır: d(10L + L²)/dL = 10 + 2L.'),
  ('Monopson piyasasında asgari ücretin belirli bir aralıkta konmasının istihdamı artırabilmesinin nedeni nedir?', 'Asgari ücret, işverenin marjinal maliyetini o aralıkta sabitler.', ['Asgari ücret emek arzını azaltır ve verimliliği kendiliğinden düşürür.', 'Asgari ücret işverenin sabit maliyetini düşürür.', 'Asgari ücret işçilerin verimliliğini iki katına çıkarır.'], 'Asgari ücretle işveren ek işçi için ücreti artırmak zorunda kalmaz; MFC asgari ücrete eşitlenir ve istihdam monopson düzeyinin üzerine çıkabilir.'),
  ('İkili tekel modelinde fiyatın kesin olarak belirlenememesinin nedeni nedir?', 'Fiyat, pazarlık gücüne bağlı olarak bir aralıkta oluşur.', ['Talep ve arz eğrileri bu piyasada hiçbir noktada kesişmediği için denge yoktur.', 'Devlet fiyatı her yıl değiştirir.', 'Taraflar fiyatı rastgele seçer.'], 'Satıcı tekel fiyatını, alıcı monopson fiyatını ister. Gerçekleşen fiyat bu iki uç arasında, pazarlık becerisi ve alternatiflere göre belirlenir.'),
  ('Monopson gücüne sahip bir işverenle karşılaşan işçilerin sendikalaşması kuramsal olarak istihdamı nasıl etkileyebilir?', 'Ücreti yükseltirken istihdamı da artırabilir.', ['Her durumda istihdamı sıfıra indirir ve işletmenin kapanmasına yol açar.', 'Ücreti düşürüp istihdamı artırır.', 'Ne ücreti ne istihdamı etkiler.'], 'Sendikanın pazarlıkla belirlediği ücret, monopsondaki asgari ücret gibi işler; belirli bir aralıkta hem ücreti hem istihdamı rekabetçi düzeye yaklaştırabilir.'),
  ('Bir sektörde minimum etkin ölçek (MES) 50.000 birim, toplam piyasa talebi ise en düşük ortalama maliyet fiyatında 400.000 birimdir. Sektörde verimli çalışabilecek en fazla firma sayısı yaklaşık kaçtır?', '8', ['50', '4', '80'], 'Firma sayısı ≈ piyasa talebi / MES = 400.000 / 50.000 = 8.'),
  ('Bir ülkenin dış ticarete açılmasıyla yüksek MES gerektiren bir sektörde ne olması beklenir?', 'Pazar büyüdüğü için daha fazla firma verimli ölçekte çalışabilir.', ['Pazar küçüldüğü için tüm firmalar zarar etmeye başlar ve sektör kısa sürede kapanır.', 'MES kendiliğinden yükselir.', 'Sektör tekele dönüşür.'], 'Pazarın genişlemesi, aynı MES ile daha çok firmanın verimli üretmesine olanak verir; bu da rekabeti artırır.'),
  ('Reklam yoğunluğunun (reklam/satış) genellikle en yüksek olduğu piyasa yapıları hangileridir?', 'Farklılaştırılmış ürünlü oligopol ve monopolcü rekabet', ['Homojen ürünlü tam rekabet', 'Tarım ürünleri piyasası', 'Devletçe fiyatı belirlenen doğal tekel'], 'Tam rekabette ürün homojen olduğu için reklam anlamsızdır; farklılaştırılmış ürün sunan az ya da çok sayıda firma ise marka ayrıştırmak için yoğun reklam yapar.'),
  ('Kenneth Arrow\'un 1962\'de ortaya koyduğu \'ikame (yerini alma) etkisi\' neyi açıklar?', 'Tekelin yenilik güdüsünün rekabetçi firmanınkinden zayıf olabileceğini', ['Tekelin rakiplerine göre her durumda daha çok Ar-Ge yapıp daha çok yenilik ürettiğini', 'Yeniliklerin fiyatları artırdığını', 'Patentlerin yeniliği engellediğini'], 'Tekel yenilik yaptığında zaten elde ettiği tekel kârının yerine yenisini koyar; rekabetçi firma ise sıfırdan tekel kârı kazanır. Bu yüzden yeniliğin tekele ek getirisi daha küçüktür.'),
  ('Schumpeter\'in \'Kapitalizm, Sosyalizm ve Demokrasi\' (1942) kitabındaki görüşünden türetilen \'Schumpeter hipotezi\' neyi öne sürer?', 'Büyük firmaların ve piyasa gücünün yeniliği teşvik ettiğini', ['Küçük firmaların hiç yenilik yapmadığını', 'Tam rekabetin en çok yeniliği ürettiğini', 'Devletin tüm Ar-Ge\'yi yapması gerektiğini'], 'Schumpeter\'e göre tekel kârı Ar-Ge\'yi finanse eder ve yenilikten elde edilecek kârın korunması güdüsünü artırır; bu nedenle büyük firmalar yeniliğin motorudur.'),
  ('Patent sisteminin piyasa yapısı açısından temel ödünleşimi nedir?', 'Yenilik güdüsü yaratırken geçici tekel gücü nedeniyle refah (ölü ağırlık) kaybına yol açması', ['Buluşun fiyatını kalıcı olarak marjinal maliyete indirip kârı sıfırlaması', 'Yeniliği tümüyle ortadan kaldırması', 'Tüm firmalara aynı teknolojiyi zorunlu kılması'], 'Patent, buluşçuya geçici tekel vererek Ar-Ge\'nin getirisini korur; bu süre boyunca fiyat MC\'nin üzerinde kalır ve ölü ağırlık kaybı oluşur.'),
  ('Ronald Coase\'un 1972\'de ortaya koyduğu \'Coase varsayımına\' göre dayanıklı bir mal satan tekel neden zorlanır?', 'Gelecekte fiyatı düşüreceği beklentisi tüketicileri beklemeye iter.', ['Dayanıklı malların marjinal maliyeti sonsuzdur ve tekel her birim için zarar eder.', 'Dayanıklı mallar yasal olarak tekel konusu olamaz.', 'Tüketiciler dayanıklı mallara hiç talep göstermez.'], 'Tekel bugün yüksek fiyatla satıp yarın kalan alıcılara indirim yapma güdüsüne sahiptir; bunu bilen tüketiciler bekler ve fiyat rekabetçi düzeye doğru iner.'),
  ('Dayanıklı mal tekelinin Coase sorununu aşmak için başvurabileceği yöntemlerden biri hangisidir?', 'Malı satmak yerine kiralamak', ['Fiyatı her ay düşürmeyi taahhüt etmek', 'Malın dayanıklılığını artırmak', 'Rakiplerine lisans vermek'], 'Kiralama, tekelin gelecekte fiyat düşürme güdüsünü ortadan kaldırır; IBM ve Xerox\'un geçmişte makinelerini satmak yerine kiralaması bu sorunla ilişkilendirilmiştir.'),
  ('Zirve yük fiyatlamasının toplumsal açıdan yararlarından biri hangisidir?', 'Talebi zirve dışı saatlere kaydırarak gereken kapasiteyi azaltması', ['Tüm saatlerde fiyatı aynı düzeye çekip tüketicilerin karar vermesini kolaylaştırması', 'Üreticinin sabit maliyetini tamamen ortadan kaldırması', 'Tüketicilerin toplam tüketimini sıfırlaması'], 'Zirvede yüksek fiyat, esnek tüketicileri başka saatlere yönlendirir; böylece daha az kapasite yatırımıyla aynı hizmet sunulabilir.'),
  ('Bir doğal tekelin \'maliyet fonksiyonunun alt toplamsallığı\' (subadditivity) ne anlama gelir?', 'Tüm üretimi tek firmanın yapmasının daha ucuz olması', ['Toplam maliyetin üretim arttıkça giderek daha hızlı yükselmesi', 'Sabit maliyetin sıfır olması', 'Ortalama maliyetin sabit kalması'], 'William Baumol\'ün tanımıyla doğal tekel, ilgili üretim düzeyinde maliyet fonksiyonunun alt toplamsal olmasıdır; ölçek ekonomisi bunun yeterli ama gerekli olmayan koşuludur.'),
  ('Yarışılabilir piyasalar kuramında \'vur-kaç\' (hit-and-run) girişin mümkün olması için en kritik koşul hangisidir?', 'Batık maliyetlerin bulunmaması', ['Talebin tam inelastik olması', 'Piyasada en az on firma olması', 'Devletin fiyatları belirlemesi'], 'Batık maliyet yoksa yeni giren kâr fırsatını değerlendirip, yerleşik firma tepki verince kayıpsız çıkabilir; bu tehdit yerleşik firmayı rekabetçi davranmaya zorlar.'),
  ('Dirsekli talep modelinde marjinal hasılat eğrisinde mevcut miktarda bir boşluk (süreksizlik) bulunmasının sonucu nedir?', 'Marjinal maliyetteki küçük değişiklikler fiyatı değiştirmez.', ['Marjinal maliyetteki her küçük değişiklik fiyatı hemen değiştirir ve fiyatlar sürekli dalgalanır.', 'Firma her dönem fiyatı değiştirir.', 'Firma üretimi sıfıra indirir.'], 'MC eğrisi MR\'deki boşluk içinde yer değiştirdiği sürece kârı en yükselten fiyat ve miktar aynı kalır; bu da fiyat katılığını açıklar.'),
  ('Dirsekli talep modeline yöneltilen temel eleştiri hangisidir?', 'Fiyatın ilk başta nasıl oluştuğunu açıklamaması', ['Talep eğrisinin her fiyat düzeyinde tümüyle yatay varsayılması', 'Yalnızca tam rekabette geçerli olması', 'Firma sayısının bire indirgenmesi'], 'Model, mevcut fiyatın katılığını açıklar ama bu fiyatın nasıl belirlendiğini açıklamaz; George Stigler\'in ampirik çalışması da beklenen katılığı doğrulamamıştır.'),
  ('İhaleye katılan firmaların önceden kimin kazanacağını ve teklif düzeylerini kararlaştırmasına rekabet hukukunda ne ad verilir?', 'Teklif danışıklılığı', ['Hâkim durumun kötüye kullanılması', 'Münhasır bayilik', 'Sınır fiyatlaması'], 'Teklif danışıklılığı (bid rigging) bir kartel türüdür; firmalar sırayla kazanır ya da \'koruma\' amaçlı yüksek teklifler verir.'),
  ('Kartelin belirlediği yüksek fiyatın kartel dışındaki üreticiler için ne anlama geldiği göz önüne alındığında, kartelin uzun dönemde karşılaştığı tehdit hangisidir?', 'Kartel dışı üreticilerin arzını artırması', ['Talebin kendiliğinden tümüyle inelastik hâle gelip sabit kalması', 'Kartel dışı üreticilerin piyasadan çıkması', 'Kartel üyelerinin maliyetlerinin sıfıra inmesi'], 'Yüksek fiyat, kartel dışı arzı ve ikame ürünleri teşvik eder; kartelin pazar payı aşınır. 1970\'lerdeki petrol fiyat artışı sonrası Kuzey Denizi üretimi buna örnektir.'),
  ('Tam rekabet uzun dönem dengesinde fiyat 20 TL\'dir ve her firma en düşük ortalama maliyet noktasında 100 birim üretmektedir. Piyasa talebi bu fiyatta 12.000 birimse sektörde kaç firma vardır?', '120', ['100', '200', '60'], 'Firma sayısı = piyasa miktarı / firma başına miktar = 12.000 / 100 = 120.'),
  ('Tam rekabet uzun dönem dengesinde her firmanın üretimi 50 birimdir ve piyasada 80 firma vardır. Sabit maliyetli sektörde talep %25 artarsa yeni uzun dönem dengesinde kaç firma olur?', '100', ['80', '125', '64'], 'Fiyat ve firma başına üretim değişmez; toplam miktar 4.000\'den 5.000\'e çıkar. 5.000 / 50 = 100 firma.'),
  ('Monopolcü rekabet piyasasındaki bir firmanın talebi P = 50 − Q, marjinal maliyeti sabit 10 TL\'dir ve sabit maliyeti 400 TL\'dir. Kısa dönem kârı kaç TL\'dir?', '0 TL', ['400 TL', '800 TL', '200 TL'], 'MR = 50 − 2Q = 10 ⇒ Q = 20, P = 30. Kâr = (30 − 10) × 20 − 400 = 400 − 400 = 0. Firma uzun dönem dengesindedir.'),
  ('Monopolcü rekabetteki firmalar ekonomik zarar ediyorsa uzun dönemde kalan firmaların talep eğrilerine ne olur?', 'Firmalar çıktıkça kalanların talebi sağa kayar.', ['Firmalar girdikçe kalanların talebi sola kayar ve iyice daralır.', 'Talep eğrileri yatay hâle gelir.', 'Talep eğrileri değişmez.'], 'Zarar eden firmalar piyasadan çıkınca müşterileri kalan firmalara dağılır; talepleri artar ve zarar sıfırlanana kadar süreç sürer.'),
  ('Aşağıdakilerden hangisinde tek bir satıcının piyasa gücü, ürünün yakın ikamesinin bulunmasıyla en çok sınırlanır?', 'Bir kentteki tek sinema salonu, çevrimiçi film izleme olanakları varken', ['İlaç patenti sahibi bir firma, ikame ilaç yokken', 'Tek su şebekesi işletmecisi', 'Tek elektrik iletim şirketi'], 'Tek sinema bile evde film izleme gibi yakın ikamelerle rekabet eder; bu, tekelin fiyat gücünü sınırlar. Diğer seçeneklerde yakın ikame yoktur.'),
  ('İki firma yeni bir teknoloji standardı seçiyor. Her ikisi aynı standardı seçerse kazanırlar; ancak A firması X standardını, B firması Y standardını tercih ediyor. Bu yapı hangi klasik oyuna benzer?', 'Cinsiyetler savaşı', ['Tutsak ikilemi', 'Sıfır toplamlı oyun', 'Ültimatom oyunu'], 'Cinsiyetler savaşında iki oyuncu da koordinasyonu ister ama hangi noktada buluşulacağı konusunda çıkarları çatışır; iki saf Nash dengesi vardır.'),
  ('Bir firma için \'zayıf baskın strateji\' ne demektir?', 'Rakip ne yaparsa yapsın en az diğer stratejiler kadar, bazen de daha iyi sonuç veren strateji', ['Hiçbir durumda en iyi sonucu vermeyen ve her zaman kayıp getiren strateji', 'Yalnız rakip iş birliği yaparsa kazandıran strateji', 'Rastgele seçilen strateji'], 'Kesin baskın strateji her durumda daha iyidir; zayıf baskın strateji bazı durumlarda eşit, en az bir durumda kesin olarak daha iyidir.'),
  ('Giriş oyununda giren firma girerse ve yerleşik firma uyum sağlarsa giren 10, yerleşik 20; yerleşik savaşırsa giren −5, yerleşik 5 kazanıyor. Giriş olmazsa giren 0, yerleşik 40 kazanıyor. Alt oyun yetkin dengede ne olur?', 'Giren girer, yerleşik uyum sağlar.', ['Giren girmez, çünkü savaş tehdidi inandırıcıdır ve yerleşik 40 kazanır.', 'Giren girer, yerleşik savaşır.', 'İki firma da piyasadan çıkar.'], 'Giriş olduktan sonra yerleşik firma için uyum (20) savaştan (5) iyidir; bunu bilen giren firma 10 > 0 olduğundan girer.'),
  ('Oligopolde \'bilinçli paralellik\' kavramı neyi ifade eder?', 'Firmaların anlaşmadan birbirlerinin fiyat hareketlerini izlemesini', ['Firmaların yasal bir kartel anlaşması imzalamasını', 'Firmaların aynı binada üretim yapmasını', 'Firmaların birleşerek tek firma olmasını'], 'Bilinçli paralellikte firmalar karşılıklı bağımlılığın farkındadır ve fiyatlarını benzer biçimde değiştirir; açık bir anlaşma olmadığı için tek başına hukuka aykırı sayılmayabilir.'),
  ('Bir sektörde firmaların fiyat değişikliklerini her zaman aynı gün ve aynı oranda yapması, rekabet otoritesi için tek başına kartel kanıtı mıdır?', 'Hayır; oligopolde paralel davranış bağımsız kararlarla da ortaya çıkabilir.', ['Evet; paralel fiyat değişikliği her durumda yazılı bir anlaşmanın kesin kanıtıdır.', 'Evet; çünkü oligopolde fiyatlar hiç değişmez.', 'Hayır; çünkü kartellere ceza verilmez.'], 'Ortak maliyet şokları ya da fiyat liderliği de paralel hareket doğurabilir; otoriteler bu nedenle iletişim ya da bilgi değişimi gibi ek kanıtlar arar.'),
  ('Rakip firmaların ayrıntılı, güncel ve firmaya özgü satış verilerini birbirleriyle paylaşması neden rekabet hukukunda sorunlu görülür?', 'Koordinasyonu ve sapmaların izlenmesini kolaylaştırdığı için', ['Firmaların vergi yükünü artırdığı için', 'Tüketicilerin bilgiye erişimini artırdığı için', 'Firmaların üretim maliyetlerini düşürdüğü için'], 'Bireysel ve güncel veri paylaşımı, örtülü anlaşmanın temel sorunları olan uzlaşmayı ve hileyi izlemeyi kolaylaştırır; toplulaştırılmış ve eski veriler daha az sakıncalıdır.'),
  ('Bir piyasada tek firmanın bulunması, o firmanın her zaman tekel gücü kullanabileceği anlamına gelmez. Aşağıdakilerden hangisi bunu en iyi açıklar?', 'Potansiyel giriş tehdidi ve ikame ürünler fiyat gücünü sınırlayabilir.', ['Tek firma her zaman devlet tarafından kamulaştırılır ve fiyatları kamu belirler.', 'Tek firmanın maliyeti her zaman sıfırdır.', 'Tek firmanın talebi her zaman tam esnektir.'], 'Kolay giriş ya da yakın ikameler varsa tek satıcı bile yüksek fiyat koyamaz; piyasa gücü yalnızca firma sayısına değil rekabet baskısına bağlıdır.'),
  ('Bir firmanın aynı ürünü farklı ülkelerde farklı fiyatlarla satabilmesi için ülkeler arasında hangi koşulun bulunması gerekir?', 'Malın bir ülkeden diğerine yeniden satılmasının zor ya da maliyetli olması', ['İki ülkenin aynı para birimini kullanması ve aynı vergi sistemine sahip olması', 'İki ülkede talep esnekliğinin aynı olması', 'Malın marjinal maliyetinin sıfır olması'], 'Taşıma maliyetleri, gümrük engelleri ya da garanti koşulları arbitrajı zorlaştırırsa pazarlar ayrılabilir ve farklı fiyatlar sürdürülebilir.'),
  ('Bir firma indirim kuponlarını yalnızca gazeteden kesip saklama zahmetine katlanan tüketicilere veriyor. Kuponların fiyat farklılaştırması aracı olarak işlevi nedir?', 'Fiyata duyarlı tüketicileri kendiliğinden ayırmak', ['Tüm tüketicilere aynı indirimi otomatik olarak uygulayıp fiyatları eşitlemek', 'Firmanın maliyetini düşürmek', 'Fiyat duyarlılığı düşük tüketicilere daha ucuz satmak'], 'Kupon toplamak zaman ve çaba ister; buna katlananlar genellikle fiyata daha duyarlı olanlardır. Böylece firma onlara düşük, diğerlerine yüksek fiyat uygular.'),
  ('Bir havayolunun aynı koltuğu uçuş tarihine yaklaştıkça daha pahalıya satması hangi tüketici özelliğinden yararlanır?', 'Son dakika yolcularının (çoğunlukla iş seyahati) talebinin daha az esnek olması', ['Son dakika yolcularının talebinin tam esnek olması', 'Erken alıcıların fiyata hiç duyarlı olmaması', 'Uçuş maliyetinin son günlerde iki katına çıkması'], 'Planlı tatilciler erken ve fiyata duyarlı alır; son anda bilet arayan iş yolcuları ise yüksek fiyatı kabul eder. Zamanlama bir ayırma aracıdır.'),
  ('Rekabet hukukuna adını veren \'antitröst\' sözcüğündeki \'tröst\' neyi ifade eder?', 'Şirket hisselerinin tek bir heyete devredilerek birleştirildiği yapıyı', ['Bankaların mevduat sahiplerine verdiği ve devletçe güvence altına alınan belgeyi', 'Bir devletin dış ticareti tekeline alan kurumunu', 'İşçi sendikalarının ortak fonunu'], '19. yüzyıl ABD\'sinde Standard Oil gibi şirketler, rakip firmaların hisselerini bir mütevelli heyetine (trust) devrettirerek tek elden yönetilen dev yapılar kurmuştur.'),
  ('Osmanlı esnaf düzeninde bir zanaatı ya da ticareti yapabilme hakkını belgeleyen ve dükkân sayısını sınırlayan uygulamaya ne ad verilir?', 'Gedik', ['Narh', 'İltizam', 'Müsadere'], 'Gedik sistemi, belirli bir meslekte faaliyet gösterebilecek usta ve dükkân sayısını sınırlayarak yasal bir giriş engeli işlevi görmüştür.'),
  ('Osmanlı\'da kadıların belirlediği ve esnafın aşamayacağı azami satış fiyatına ne ad verilir?', 'Narh', ['Gedik', 'Cizye', 'Avarız'], 'Narh, loncaların tekel gücünü sınırlayan bir fiyat denetimi aracıdır; ihtisap ağaları narha uyulup uyulmadığını denetlerdi.'),
  ('Ortaçağ Avrupa\'sında loncaların ekonomik açıdan eleştirilmesinin temel nedeni nedir?', 'Mesleğe girişi kısıtlayarak tekel benzeri bir güç oluşturmaları', ['Üyelerine sınırsız rekabet ortamı sağlayıp fiyatları sürekli düşürmeleri', 'Devlete hiç vergi ödememeleri', 'Yalnız tarım ürünleri üretmeleri'], 'Loncalar çıraklık kuralları ve üye sayısı sınırlamalarıyla girişi denetlemiş, fiyat ve üretim kurallarıyla rekabeti kısıtlamıştır.'),
  ('Bir kamu tekelinin özelleştirilmesinin rekabet açısından yararlı olması için genellikle hangi önlemin birlikte alınması gerekir?', 'Piyasaya girişin serbestleştirilip bağımsız düzenleme yapılması', ['Tekelin özel bir şirkete olduğu gibi devredilip tüm düzenlemelerin kaldırılması', 'Fiyatların özelleştirmeden sonra dondurulması', 'Tüketicilerin tek tedarikçiye bağlanması'], 'Kamu tekelini özel tekele dönüştürmek tek başına rekabet getirmez; giriş engellerinin kaldırılması ve sektörel düzenleyicinin varlığı gerekir.'),
  ('Bir şebeke sahibinin rakiplere şebeke erişimi için yüksek toptan fiyat, kendi perakende müşterilerine ise düşük fiyat uygulayarak rakiplerin kâr marjını yok etmesine ne ad verilir?', 'Fiyat sıkıştırması (marj sıkıştırması)', ['Çifte marjinalleşme (ardışık kâr marjı)', 'Zirve yük fiyatlaması', 'Ramsey fiyatlaması'], 'Dikey bütünleşik hâkim firma, toptan ve perakende fiyatları arasındaki farkı rakiplerin verimli biçimde kâr edemeyeceği kadar daraltırsa bu, hâkim durumun kötüye kullanılması sayılabilir.'),
  ('Telekomünikasyon gibi şebeke sektörlerinde düzenleyicilerin yerleşik operatörden \'yerel ağın paylaşıma açılmasını\' istemesinin amacı nedir?', 'Rakiplerin şebekeyi kopyalamadan hizmet sunabilmesini sağlamak', ['Yerleşik operatörün yeni yatırım yapmasını yasaklayıp şebekeyi kamulaştırmak', 'Tüketicilerin operatör değiştirmesini engellemek', 'Fiyatları tekel düzeyine çıkarmak'], 'Yerel ağı kopyalamak çok pahalıdır; erişim zorunluluğu, rakiplerin bu doğal tekel unsurunu kullanarak perakende düzeyde rekabet etmesini mümkün kılar.'),
  ('İki rakip ağın birbirine bağlanmayı (ara bağlantı) reddetmesi, büyük ağ ile küçük ağ arasındaki rekabeti nasıl etkiler?', 'Büyük ağın avantajını büyütür.', ['Küçük ağın avantajını büyüterek pazar payını hızla artırır.', 'Rekabeti hiç etkilemez.', 'İki ağın değerini eşitler.'], 'Ara bağlantı yoksa kullanıcılar yalnızca kendi ağlarındakilere ulaşabilir; bu da en çok kullanıcıya sahip ağı çekici kılar ve küçük ağları dışlar.'),
  ('Ağ dışsallıklarının güçlü olduğu piyasalarda firmalar arasındaki rekabet çoğunlukla nasıl tanımlanır?', 'Piyasa içinde değil, piyasa için rekabet', ['Fiyatların sürekli marjinal maliyette kaldığı tam rekabet', 'Kartel içi rekabet', 'Yalnızca reklam rekabeti'], 'Kazanan piyasanın büyük bölümünü alacağı için firmalar standardı belirleme yarışına girer; rekabet piyasayı ele geçirmek üzerine yoğunlaşır.'),
  ('İki taraflı bir platformun bir taraftaki fiyatı artırmasının platform üzerindeki etkisi neden tek taraflı bir firmadakinden karmaşıktır?', 'O tarafın kullanıcı sayısı azalınca diğer taraf için platformun değeri de düşer.', ['Diğer taraftaki kullanıcı sayısı her zaman tam olarak sabit kalır ve hiç etkilenmez.', 'İki taraflı platformlarda fiyatlar yasayla belirlenir.', 'Platformun maliyeti fiyatla birlikte artar.'], 'Taraflar arası ağ etkisi nedeniyle bir taraftaki kayıp diğer tarafın talebini de düşürür; platform fiyatları birlikte düşünmek zorundadır.'),
  ('Bir kredi kartı şirketinin kart sahiplerine ödül puanı verip, maliyeti işyerlerinden alınan komisyonla karşılaması hangi kavramla açıklanır?', 'İki taraflı piyasada fiyat yapısı', ['Ters esneklik kuralının tam rekabete uygulanması', 'Dayanıklı mal tekeli', 'Ölçek eksi ekonomisi'], 'Kart sistemi, kart sahiplerini çekmek için onları sübvanse eder; işyerleri ise çok sayıda kart sahibine ulaşmak için komisyon ödemeye razıdır.'),
  ('Bir yazılım firmasının kendi işletim sistemine ücretsiz bir uygulamayı önceden yüklemesi, rakip uygulamalar açısından hangi rekabet kaygısını doğurur?', 'Bağlama yoluyla rakiplerin dışlanması', ['Çifte marjinalleşmenin ortadan kalkıp fiyatların düşmesi', 'Ramsey fiyatlaması', 'Zirve yük fiyatlaması'], 'Hâkim işletim sistemine bağlanan uygulama, kullanıcılara varsayılan olarak ulaşır; rakipler ürünleri daha iyi olsa bile dağıtım dezavantajı yaşar.'),
  ('Hâkim durumdaki bir firmanın, kendi platformunda kendi ürünlerini rakip ürünlerden daha görünür sıralamasına rekabet hukukunda ne ad verilir?', 'Kendini kayırma', ['Fiyat liderliği', 'Sınır fiyatlaması', 'Barometrik liderlik'], 'Kendini kayırma (self-preferencing), dikey bütünleşik platformların aşağı pazardaki rakipleri dezavantajlı duruma düşürmesi biçiminde ortaya çıkan bir kötüye kullanma türüdür.'),
  ('Rekabetçi bir sektör tek bir firma tarafından satın alınıp tekele dönüşüyor. Talep P = 100 − Q, marjinal maliyet sabit 20 TL\'dir. Tüketici rantı kaç TL azalır?', '2.400 TL', ['3.200 TL', '800 TL', '1.600 TL'], 'Rekabette Q = 80, P = 20 ve tüketici rantı ½ × 80 × 80 = 3.200 TL. Tekelde Q = 40, P = 60 ve rant ½ × 40 × 40 = 800 TL. Azalış 2.400 TL\'dir.'),
  ('Talep P = 100 − Q ve marjinal maliyetlerin sıfır olduğu bir piyasada iki firmalı Cournot dengesinde her firmanın kârı yaklaşık 1.111 TL\'dir. Firmalar kartel kurup tekel kârını eşit paylaşırsa her birinin kârı kaç TL olur?', '1.250 TL', ['2.500 TL', '1.111 TL', '625 TL'], 'Tekel Q = 50, P = 50 seçer ve 2.500 TL kâr eder; eşit paylaşımda her firmaya 1.250 TL düşer. Bu, Cournot kârından yüksektir.'),
  ('Talebi sabit esneklikli ve esnekliği mutlak değerce 2 olan bir ürünü üreten tekelin marjinal maliyeti 15 TL\'dir. Tekel fiyatı kaç TL\'dir?', '30 TL', ['20 TL', '45 TL', '22,50 TL'], 'P = MC/(1 − 1/|e|) = 15/(1 − 0,5) = 30 TL. Esneklik 2 iken fiyat marjinal maliyetin iki katıdır.'),
  ('Talebi P = 100 − Q ve marjinal maliyeti 20 TL olan bir tekele 40 TL\'lik bir tavan fiyat konuyor. Tekelin üretimi nasıl değişir?', '40\'tan 60\'a çıkar.', ['40\'tan 30\'a düşer ve kıtlık oluşur.', 'Değişmez, 40 kalır.', '80\'e çıkar.'], 'Tavan fiyat 40 TL\'yken tekel bu fiyattan talep edilen 60 birime kadar sabit marjinal hasılatla (40) satar; 40 > MC = 20 olduğundan 60 birim üretir.'),
  ('Tam rekabette tavan fiyat üretimi azaltırken tekelde uygun bir tavan fiyatın üretimi artırabilmesinin nedeni nedir?', 'Tavan fiyat tekelin marjinal hasılatını o aralıkta fiyata eşit ve sabit yapar.', ['Tavan fiyat tekelin marjinal maliyetini sıfıra indirerek her birimi bedava üretmesini sağlar.', 'Tekelin talebi tavan fiyatla tam inelastik olur.', 'Tekel tavan fiyatı göz ardı edebilir.'], 'Tavan altında tekel daha fazla satmak için fiyat indirmek zorunda kalmaz; MR = tavan fiyat olur ve üretimi MC\'nin bu fiyata ulaştığı ya da talebin bittiği noktaya kadar artırır.'),
  ('Tekelci bir firmanın sabit maliyeti artarsa ama talep ve marjinal maliyet değişmezse uzun dönemde ne olabilir?', 'Kâr negatife dönerse firma piyasadan çıkabilir.', ['Fiyatı sabit maliyet artışı kadar yükseltir ve satış miktarını korur.', 'Üretimini hemen artırır.', 'Marjinal hasılatı yükselir.'], 'Sabit maliyet kısa dönemde üretim kararını etkilemez; fakat uzun dönemde tüm maliyetler değişken olduğundan, en iyi noktada bile kâr negatifse firma çıkar.'),
  ('Tam rekabet piyasasında birim başına vergi konunca fiyat artışı ile tekelde aynı vergi konunca fiyat artışı karşılaştırıldığında (doğrusal talep, sabit MC) hangisi doğrudur?', 'Tam rekabette vergi tümüyle, tekelde yarısı fiyata yansır.', ['Tekelde vergi iki katı fiyata yansırken tam rekabette hiç yansımaz.', 'İkisinde de vergi tümüyle fiyata yansır.', 'İkisinde de verginin yarısı fiyata yansır.'], 'Sabit MC\'li rekabetçi sektörde arz yatay olduğundan fiyat MC + t olur; tekelde ise doğrusal talepte fiyat t/2 artar.'),
  ('Bir firmanın talebi P = 40 − 0,5Q\'dur. Fiyat 30 TL iken talebin fiyat esnekliği mutlak değerce kaçtır?', '3', ['1,5', '0,33', '2'], 'P = 30 ⇒ Q = 20. Esneklik = (dQ/dP)(P/Q) = 2 × 30/20 = 3.'),
  ('Bir tekelin aynı ürünü iki ayrı pazarda farklı fiyatlarla sattığı durumda, pazarlardan birinde talep tümüyle esnek hâle gelirse o pazarda fiyat ne olur?', 'Marjinal maliyete eşitlenir.', ['Diğer pazardaki fiyatın iki katına çıkar ve sabit kalır.', 'Sıfıra düşer.', 'Tekel fiyatı olarak kalır.'], 'Tam esnek talepte MR = P olur; MR = MC koşulu fiyatı marjinal maliyete eşitler. Bu pazarda tekel fiyat gücünü yitirir.'),
  ('Ölü ağırlık kaybının büyüklüğü, tekelin karşılaştığı talebin esnekliğiyle (diğer koşullar sabitken) nasıl ilişkilidir?', 'Talep daha az esnek olduğunda marj büyüdüğünden kayıp genellikle artar.', ['Talep esnekliği ne olursa olsun ölü ağırlık kaybı her zaman sıfırdır.', 'Talep tam esnekken kayıp en yüksektir.', 'Esneklik kaybı etkilemez.'], 'Esnekliği düşük talepte tekel fiyatı MC\'nin çok üzerine koyabilir; fiyat-maliyet farkı büyüdükçe kayıp üçgeni de genişler.'),
  ('Dört firmalı bir Cournot oligopolünde talep P = 100 − Q ve marjinal maliyetler sıfırdır. Denge fiyatı kaç TL\'dir?', '20 TL', ['25 TL', '50 TL', '33,33 TL'], 'Her firma 100/(n + 1) = 20 üretir; toplam 80, fiyat 100 − 80 = 20 TL.'),
  ('İki özdeş firmalı homojen ürün piyasasında Cournot ve Bertrand modelleri aynı talep ve maliyetle çözüldüğünde hangi sonuç doğrudur?', 'Bertrand fiyatı Cournot fiyatından düşüktür.', ['Cournot fiyatı Bertrand fiyatından düşüktür ve marjinal maliyetin altına iner.', 'İki modelde fiyatlar her zaman eşittir.', 'Bertrand modelinde firmalar tekel kârı eder.'], 'Bertrand\'da fiyat MC\'ye iner; Cournot\'da ise firmalar miktarı kıstığı için fiyat MC\'nin üzerinde kalır.'),
  ('Sabit marjinal maliyetli bir tekelin talebi P = 50 − Q\'dan P = 70 − Q\'ya kayıyor; MC = 10 TL. Tekel fiyatı kaç TL artar?', '10 TL', ['20 TL', '5 TL', '15 TL'], 'İlk durumda Q = 20, P = 30; ikinci durumda Q = 30, P = 40. Fiyat 10 TL artar (talep kesiminin artışının yarısı).'),
  ('Bir tekel kısa dönemde zarar ediyor ama fiyat ortalama değişken maliyetin üzerindedir. Uzun dönemde aynı koşullar sürerse ne beklenir?', 'Firma piyasadan çıkar ya da tesis ölçeğini değiştirir.', ['Firma ekonomik kâr elde etmeye başlar ve yeni rakipler piyasaya girer.', 'Firma kısa dönem davranışını sonsuza dek sürdürür.', 'Talep kendiliğinden tam inelastik olur.'], 'Uzun dönemde sabit maliyet kalmaz; fiyat ortalama toplam maliyeti karşılamıyorsa tekel de çıkış ya da yeniden yapılanma kararı verir.'),
  ('Tekelci bir firmanın talebi kısa dönemde birim esnek bölgede P = 40 TL ise ve marjinal maliyeti pozitifse firma için hangi öneri doğrudur?', 'Fiyatı artırıp üretimi azaltmalıdır.', ['Fiyatı düşürüp üretimi artırarak hasılatını ve kârını büyütmelidir.', 'Fiyatı aynı tutmalıdır, en iyi noktadadır.', 'Üretimi durdurmalıdır.'], 'Birim esnek noktada MR = 0\'dır; MC > 0 olduğundan MR < MC\'dir. Üretimi azaltıp fiyatı yükseltmek maliyeti hasılattan daha çok düşürür ve kârı artırır.'),
  ('Tutsak ikilemi bakış açısıyla, iki sigara üreticisinin reklam yasağına neden gizlice sevinebileceği nasıl açıklanır?', 'Yasak, ikisinin de tek başına bırakamadığı pahalı reklam yarışını sona erdirir.', ['Yasak, sigara talebini tam inelastik yapar ve fiyatı yasal olarak yükseltir.', 'Yasak, sigara üretim maliyetini sıfıra indirir.', 'Yasak, yeni firmaların girmesini kolaylaştırır.'], 'Reklam, rakip reklam yaptıkça bireysel olarak zorunlu hâle gelir ama toplamda pazar payını pek değiştirmez. Yasak, firmaları bu pahalı dengeden kurtarır; ABD\'de 1971 televizyon reklam yasağı bu bağlamda tartışılmıştır.'),
  ('Kartel üyelerinin birbirlerine güvenmesini zorlaştıran tutsak ikilemi yapısında, bağlayıcı ve uygulanabilir bir sözleşme bulunsaydı ne olurdu?', 'İş birliği sürdürülebilirdi.', ['Üyeler yine de her durumda kotalarını aşar ve fiyatlar düşerdi.', 'Kartel kârı sıfıra inerdi.', 'Piyasa tam rekabete dönüşürdü.'], 'Tutsak ikilemindeki sorun, verilen sözün uygulatılamamasıdır. Sapmayı cezalandıran bağlayıcı bir sözleşme olsaydı iş birliği dengeye dönüşürdü; kartel anlaşmalarının mahkemede uygulatılamaması bu yüzden önemlidir.'),
  ('Bir firmanın yıkıcı fiyatlama yaptığını kanıtlamak neden zordur?', 'Düşük fiyat, sert ama meşru rekabetten de kaynaklanabilir.', ['Firmaların maliyetleri hiçbir zaman ve hiçbir yöntemle hesaplanamaz.', 'Yıkıcı fiyatlama hiçbir ülkede yasak değildir.', 'Yıkıcı fiyatlama yalnızca kamu tekellerinde görülür.'], 'Rekabet hukuku düşük fiyatı cezalandırmaktan kaçınır; çünkü verimli firmaların düşük fiyatı tüketicinin yararınadır. Yıkıcı niyet ve telafi olasılığının ayrıca gösterilmesi gerekir.'),
  ('Bir otomobil üreticisinin yeni modelini birkaç yılda bir çıkarıp eski modeli üretimden kaldırmasının dayanıklı mal tekeli açısından bir işlevi olabilir. Bu işlev nedir?', 'Eski ürünlerin yerine yenisini aldırarak tekrar talep yaratmak', ['Eski modellerin ikinci el fiyatını yasal olarak sabitleyip piyasayı dondurmak', 'Tüketicilerin bekleme güdüsünü artırmak', 'Marjinal maliyeti sıfırlamak'], 'Planlı eskitme ya da sık model değişikliği, dayanıklı malın yeniden satın alınmasını teşvik eder; bu, dayanıklılığın tekel gücünü aşındırmasına karşı bir yoldur.'),
  ('Tam rekabet sektöründe bir girdinin fiyatı geçici olarak artarsa kısa dönemde piyasa fiyatı ve firmaların kârı nasıl etkilenir?', 'Fiyat yükselir, firmalar kısa dönemde zarar edebilir.', ['Fiyat düşer ve firmaların kârı kısa dönemde kesin olarak artar.', 'Fiyat değişmez, kârlar artar.', 'Fiyat ve kâr hiç etkilenmez.'], 'Maliyet artışı firmaların arz eğrilerini sola kaydırır; piyasa fiyatı yükselir ama maliyet artışının tamamını karşılamayabilir, bu da kısa dönemde zarara yol açabilir.'),
  ('Tam rekabetteki bir sektörde yeni bir yasa üretimi belirli bir lisansa bağlayıp lisans sayısını sınırlarsa uzun dönemde ne beklenir?', 'Mevcut firmalar ekonomik kâr elde etmeyi sürdürebilir.', ['Yeni firmalar serbestçe girer ve kârlar kısa sürede sıfıra iner.', 'Fiyat en düşük ortalama maliyete iner.', 'Tüm firmalar zarar eder.'], 'Lisans sınırı girişi engellediği için kâr yeni girişlerle aşınamaz; bu durumda lisansın kendisi değer kazanır (ör. taksi plakası fiyatları).'),
  ('Rekabet otoritesinin \'ilgili pazar\' tanımını dar yapması, bir birleşmenin değerlendirmesini genellikle nasıl etkiler?', 'Birleşen firmaların pazar payı daha yüksek görünür.', ['Birleşen firmaların pazar payı çok daha düşük görünür ve izin kolaylaşır.', 'Pazar payları hiç değişmez.', 'Birleşme otomatik olarak yasaklanır.'], 'Pazar ne kadar dar tanımlanırsa firmaların payı o kadar büyük çıkar; bu nedenle pazar tanımı birleşme davalarında sıkça tartışılır.'),
  ('Rekabet analizinde \'arz ikamesi\' neyi ifade eder?', 'Başka ürün üreten firmaların üretimlerini hızla bu ürüne kaydırabilmesi', ['Tüketicilerin fiyat artınca bir üründen ona yakın başka bir ürüne geçmesi', 'Devletin arzı belirlemesi', 'Firmaların girdileri değiştirmesi'], 'Talep ikamesi tüketicilerin başka ürüne geçmesini, arz ikamesi ise üreticilerin üretimlerini hızla bu pazara kaydırabilmesini anlatır; ikisi de pazar gücünü sınırlar.'),
  ('Aşağıdaki piyasalardan hangisinde ürün homojen ama firma sayısı az olduğundan oligopol özellikleri görülür?', 'Çimento', ['Kuaför hizmetleri', 'Lokantacılık', 'Giyim mağazacılığı'], 'Çimento standart bir üründür ve yüksek sabit maliyet nedeniyle bölgesel pazarlarda az sayıda üretici bulunur; diğerleri farklılaştırılmış hizmetlerdir.'),
  ('Bir sektördeki firmaların aynı derneğe üye olması ve dernek toplantılarında fiyat konuşması rekabet hukuku açısından neden risklidir?', 'Dernek kararları ve bilgi paylaşımı fiyat koordinasyonuna dönüşebilir.', ['Derneklere üye olmak her ülkede yasaklandığı için her toplantı suç sayılır.', 'Dernekler vergi ödemez.', 'Dernek toplantıları reklam sayılır.'], 'Rekabet yasaları \'teşebbüs birliği kararlarını\' da yasaklar; meslek ve sektör dernekleri fiyat tavsiyesi ya da hassas bilgi paylaşımı yaparsa kartel benzeri sonuç doğabilir.'),
  ('Bir firmanın çok pahalı bir reklam kampanyası yapmasının, ürününün kaliteli olduğuna dair bir \'işaret\' olabileceğini savunan görüşe göre bunun nedeni nedir?', 'Pahalı reklam, ancak tekrar satın alınan iyi ürün için kâr getirir.', ['Reklam ürünün kalitesini fiziksel olarak artırır ve maliyeti düşürür.', 'Reklam yasal kalite belgesidir.', 'Reklam yapan firma vergiden muaf tutulur.'], 'Phillip Nelson\'ın deneyim malları yaklaşımına göre yüksek reklam harcaması, ancak tekrar alım bekleyen kaliteli üreticiler için geri dönen bir yatırımdır.'),
  ('Bir buluşçunun patent hakkını başka firmalara ücret karşılığı kullandırmasının piyasa yapısına etkisi ne olabilir?', 'Ürünü üreten firma sayısını artırabilir.', ['Piyasayı hemen tam tekele dönüştürür ve tüm rakipleri dışarıda bırakır.', 'Ürünün üretimini tamamen durdurur.', 'Patent süresini sonsuza uzatır.'], 'Lisans verilmesi, patentli teknolojinin birden fazla firma tarafından kullanılmasını sağlar; bu, tek üreticili yapıdan daha rekabetçi bir yapıya yol açabilir.'),
  ('Bir doğal tekelin kamu mülkiyetinde tutulması yerine özel sektöre verilip düzenlenmesinin savunulan yararı hangisidir?', 'Kâr güdüsünün verimliliği artırması', ['Fiyatların düzenlenmeden tümüyle serbest bırakılması ve tekel kârının artması', 'Rakip firmaların piyasaya hemen girmesi', 'Ürünün ücretsiz dağıtılması'], 'Özel mülkiyet, maliyet düşürme güdüsü yaratabilir; düzenleme ise tekel gücünün kötüye kullanılmasını sınırlar.'),
  ('Cournot düopolünde talep P = 60 − Q ve marjinal maliyetler sıfırdır. Rakip 20 birim üretirse firma 1\'in en iyi yanıtı kaç birimdir?', '20', ['30', '40', '10'], 'Tepki fonksiyonu q1 = (60 − q2)/2 = (60 − 20)/2 = 20.'),
  ('Bir tekel fiyatı 100 TL\'den 90 TL\'ye indirdiğinde satışları 10\'dan 11 birime çıkıyor. Bu fiyat indiriminin toplam hasılata etkisi nedir?', 'Hasılat 1.000 TL\'den 990 TL\'ye düşer.', ['Hasılat 1.000 TL\'den 1.100 TL\'ye yükselir.', 'Hasılat değişmez.', 'Hasılat 90 TL artar.'], '10 × 100 = 1.000 TL; 11 × 90 = 990 TL. Ek birimden 90 TL kazanılırken önceki 10 birimde 100 TL kaybedilir; marjinal hasılat −10 TL\'dir.'),
  ('Doğal tekelde fiyatın ortalama maliyete eşitlendiği düzenlemede firmanın maliyetini düşürme güdüsü neden zayıf olabilir?', 'Maliyet düşüşü fiyata yansıtılıp firmanın kârı artmaz.', ['Maliyet düşüşünün tamamı firmanın kârı olarak kalır ve fiyat değişmez.', 'Firma maliyetini hiçbir zaman ölçemez.', 'Ortalama maliyet her zaman sıfırdır.'], 'Fiyat maliyete bağlandığında tasarruf tüketiciye geçer; firma için maliyet düşürmenin ödülü kalmaz. Tavan fiyat düzenlemesi bu sorunu hafifletmeyi amaçlar.'),
  ('Bir telefon operatörünün \'sınırsız konuşma\' paketine yüksek, \'kullandıkça öde\' tarifesine düşük sabit ücret koyması hangi tür fiyatlama stratejisine örnektir?', 'Tüketicilerin kendi seçtiği tarife menüsü', ['Birinci derece kişiye özel fiyatlama', 'Yıkıcı fiyatlama', 'Sınır fiyatlaması'], 'Farklı kullanım yoğunluğundaki müşteriler kendilerine uygun tarifeyi seçer; bu, ikinci derece farklılaştırmanın bir uygulamasıdır.'),
  ('Bir tema parkının yüksek giriş ücreti alıp parktaki oyuncakları ücretsiz yapması iki parçalı tarifenin hangi uç biçimidir?', 'Birim fiyatın sıfır, giriş ücretinin yüksek olduğu biçim', ['Giriş ücretinin sıfır, birim fiyatın çok yüksek olduğu biçim', 'Her iki fiyatın da sıfır olduğu biçim', 'Yalnızca birim fiyatın olduğu tek parçalı biçim'], 'Oyuncakların marjinal maliyeti çok düşükse birim fiyatı sıfıra yakın tutup tüketici rantını giriş ücretiyle almak kârı en yükseltebilir.'),
  ('Bertrand rekabetinde fiyatların marjinal maliyete inmesi en çok hangi tür piyasalarda gözlenebilir?', 'Homojen ürün satan ve kapasite kısıtı olmayan firmaların piyasalarında', ['Farklı markalı lüks ürünlerin satıldığı piyasalarda', 'Doğal tekel piyasalarında', 'Tek alıcılı piyasalarda'], 'Bertrand sonucu, ürünlerin tam ikame olduğu ve her firmanın tüm talebi karşılayabildiği koşullarda geçerlidir.'),
  ('Bir oyun konsolu üreticisinin konsolu maliyetinin altında satıp oyunlardan aldığı lisans ücretleriyle kâr etmesi hangi piyasa yapısı özelliğinden yararlanır?', 'İki taraflı platform yapısı', ['Tam rekabet piyasası', 'Kartel düzeni', 'Monopson gücü'], 'Konsol, oyuncuları ve oyun geliştiricileri buluşturan bir platformdur; oyuncuları ucuz konsolla çekip geliştiricilerden gelir elde eder.'),
  ('1883\'te Cournot\'nun kitabını eleştirerek firmaların miktar yerine fiyat seçmesi gerektiğini öne süren Fransız matematikçi kimdir?', 'Joseph Bertrand', ['Léon Walras', 'Jules Dupuit', 'Augustin Cauchy'], 'Joseph Bertrand\'ın 1883 tarihli eleştirisi, bugün Bertrand modeli olarak bilinen fiyat rekabeti yaklaşımının temelidir.'),
  ('Herfindahl-Hirschman endeksi adını hangi iki iktisatçıdan alır?', 'Orris Herfindahl ve Albert Hirschman', ['Harold Hotelling ve Albert Hirschman', 'Orris Herfindahl ve Harold Hotelling', 'John Hicks ve Albert Hirschman'], 'Hirschman 1945\'te dış ticaret yoğunlaşması için, Herfindahl ise 1950\'de çelik sektörü üzerine tezinde benzer ölçüyü önermiştir.'),
  ('Tek bir firmanın tamamladığı bir dikey zincirde (üretici + perakendeci) son tüketici fiyatı, ayrı ayrı tekel olan üretici ve perakendecinin oluşturduğu zincire göre nasıldır?', 'Daha düşüktür.', ['Daha yüksektir ve satış miktarı da daha azdır.', 'Tam olarak aynıdır.', 'Her zaman marjinal maliyetin altındadır.'], 'Bütünleşik firma tek bir marj koyar; ayrı tekeller ise ikişer marj ekler. Çifte marjinalleşmenin ortadan kalkması fiyatı düşürür ve satışı artırır.'),
  ('Hâkim durumdaki bir firmanın, rakipleri dışlamadan yalnızca müşterilerine maliyetle hiç ilişkisi olmayan aşırı yüksek fiyatlar uygulaması hangi tür kötüye kullanma sayılır?', 'Sömürücü kötüye kullanma', ['Dışlayıcı kötüye kullanma', 'Uyumlu eylem', 'Yatay birleşme'], 'Rekabet hukukunda kötüye kullanma iki ana gruba ayrılır: rakipleri piyasadan iten dışlayıcı davranışlar ve müşterileri doğrudan zarara uğratan aşırı fiyat gibi sömürücü davranışlar.'),
  ('Bir firmanın bir pazardaki hâkim gücünü bağlama ya da paketleme yoluyla komşu bir pazara taşımaya çalışmasına rekabet iktisadında ne ad verilir?', 'Kaldıraç etkisi', ['Çifte marjinalleşme', 'Ölçek ekonomisi', 'Fiyat liderliği'], 'Kaldıraç, bir pazardaki tekel gücünü başka bir pazarda avantaj sağlamak için kullanmaktır; Microsoft davaları bu kaygının bilinen örnekleridir.'),
  ('Bir arama motorunun kullanıcılara ücretsiz hizmet verip gelirini reklamverenlerden elde etmesi iki taraflı piyasalar açısından nasıl açıklanır?', 'Kullanıcı tarafı sübvanse edilir, gelir reklamveren tarafından elde edilir.', ['Kullanıcılar reklamverenlerden daha yüksek ücret ödediği için', 'Reklamverenlerin talebi tam esnek olduğu için', 'Arama motorunun hiç maliyeti olmadığı için'], 'Çok sayıda kullanıcı reklamverenler için değerlidir; platform bu yüzden kullanıcıları ücretsiz hizmetle çeker ve reklam gelirinden kazanır.'),
  ('ABD beyzbol liglerinde uzun süre uygulanan ve oyuncuların sözleşme bitse bile başka kulübe serbestçe geçmesini engelleyen \'rezerv maddesi\' kulüplere hangi tür güç sağlamıştır?', 'Oyunculara karşı monopson gücü', ['Biletlerde tam rekabet', 'Yayın gelirlerinde fiyat liderliği', 'Tüketicilere karşı fiyat farklılaştırması'], 'Oyuncu yalnızca bir kulüple pazarlık edebildiği için kulüp, emeğin tek alıcısı gibi davranıp ücretleri rekabetçi düzeyin altında tutabilmiştir; madde 1975\'teki tahkim kararıyla çözülmüştür.'),
  ('Monopson gücüne sahip bir işverenin kârını en yükseltmek için işçi alırken karşılaştırdığı iki büyüklük hangileridir?', 'Emeğin marjinal ürün değeri ile marjinal faktör maliyeti', ['Ücret ile ortalama sabit maliyet', 'Fiyat ile ortalama değişken maliyet', 'Toplam hasılat ile toplam vergi'], 'Monopson, ek işçinin getirdiği gelir (MRP) ile ona maliyeti (MFC) eşitlenene kadar işçi alır.'),
  ('Doğal tekelde fiyatı marjinal maliyete eşitleyip doğan zararı vergilerle finanse edilen bir sübvansiyonla kapatmanın sakıncası nedir?', 'Vergiler başka piyasalarda etkinlik kaybı yaratır.', ['Sübvansiyon firmanın üretimini her durumda yarıya indirir.', 'Tüketiciler ürünü hiç kullanamaz.', 'Firma tekel fiyatı koymaya devam eder.'], 'Marjinal maliyet fiyatlaması bu piyasada etkin üretim sağlar; ancak gereken kamu geliri vergilerle toplandığından ekonominin başka yerlerinde ölü ağırlık kaybı doğar.'),
  ('Monopolcü rekabetteki bir firma kısa dönemde ekonomik kâr ediyorsa talep eğrisi ile ortalama toplam maliyet eğrisi arasındaki ilişki nasıldır?', 'Talep eğrisi bir bölümde ortalama maliyetin üzerindedir.', ['Talep eğrisi her noktada ortalama maliyetin altındadır.', 'İki eğri yalnızca teğettir.', 'İki eğri birbirine paraleldir.'], 'Kâr için seçilen miktarda P > ATC olmalıdır; bu da talebin bir aralıkta ATC\'nin üstünde kalmasıdır. Giriş oldukça talep içe kayar ve teğetlik oluşur.'),
  ('Hotelling türü bir modelde tüketicilerin ulaşım maliyeti yükselirse firmaların fiyat belirleme gücü nasıl etkilenir?', 'Artar; tüketiciler uzaktaki rakibe daha zor geçer.', ['Azalır; tüketiciler rakibe daha kolay geçer.', 'Değişmez.', 'Fiyat sıfıra iner.'], 'Ulaşım maliyeti, ürünler arasındaki farklılaşmanın ölçüsü gibidir; yüksek ulaşım maliyeti yakın müşterileri firmaya bağlar ve fiyat rekabetini yumuşatır.'),
  ('İki oyuncunun da baskın stratejisi bulunan bir oyunda Nash dengesi nasıl belirlenir?', 'İki oyuncunun baskın stratejilerinin bileşimi dengedir.', ['Toplam kazancın en düşük olduğu hücre dengedir.', 'Oyunun hiçbir zaman dengesi olmaz.', 'Denge yalnızca karma stratejilerle bulunur.'], 'Baskın strateji rakibin her seçimine karşı en iyi yanıttır; iki oyuncu da baskın stratejisini oynarsa karşılıklı en iyi yanıt, yani Nash dengesi oluşur.'),
  ('Bugün bilinen \'Monopoly\' masa oyununun öncülü sayılan \'The Landlord\'s Game\' (1904), tasarımcısı Elizabeth Magie tarafından hangi amaçla hazırlanmıştır?', 'Toprak tekelinin ve rant birikiminin sakıncalarını göstermek', ['Çocuklara tam rekabet piyasasının yararlarını öğretmek', 'Borsa yatırımını özendirmek', 'Devlet tahvillerini tanıtmak'], 'Magie, Henry George\'un görüşlerinden etkilenerek mülk sahiplerinin rant yoluyla zenginleşip ötekileri yoksullaştırdığını göstermek isteyen bir oyun tasarlamıştır.'),
  ('Fiyat farklılaştırmasını birinci, ikinci ve üçüncü derece olarak sınıflandıran ve bu ayrımı 1920 tarihli \'The Economics of Welfare\' kitabında yapan iktisatçı kimdir?', 'Arthur Cecil Pigou', ['Alfred Marshall', 'John Maynard Keynes', 'Joan Robinson'], 'Pigou\'nun üçlü sınıflandırması bugün de fiyat farklılaştırmasının standart çerçevesidir.'),
  ('George Stigler\'in 1961 tarihli \'The Economics of Information\' makalesine göre aynı ürünün farklı mağazalarda farklı fiyatlarla satılabilmesinin nedeni nedir?', 'Tüketicilerin fiyat araştırmasının maliyetli olması', ['Ürünlerin fiziksel olarak tümüyle farklı olması', 'Devletin fiyatları mağazaya göre belirlemesi', 'Satıcıların tamamının yasal tekel konumunda bulunması ve fiyatları serbestçe belirlemesi'], 'Arama maliyeti yüksekse tüketiciler tüm fiyatları öğrenmeden alım yapar; bu da tek fiyat yerine bir fiyat dağılımının kalıcı olmasına izin verir.'),
  ('Cournot modelindeki denge, oyun teorisinin hangi genel denge kavramının özel bir uygulamasıdır?', 'Nash dengesi', ['Pareto optimumu', 'Walras dengesi', 'Minimaks dengesi'], 'Cournot dengesinde her firma, rakibin miktarı veriyken en iyi miktarı seçer; bu, Nash dengesinin miktar rekabetine uygulanmış biçimidir ve bu nedenle \'Cournot-Nash dengesi\' de denir.'),
  ('Bir sektörde aynı yatırımcıların birden fazla rakip firmada önemli hisselere sahip olmasının (ortak sahiplik) rekabet üzerindeki olası etkisi nedir?', 'Firmaların birbiriyle sert rekabet etme güdüsünü zayıflatabilir.', ['Firmaları her durumda daha sert bir fiyat rekabetine girmeye zorlar.', 'Firmaların maliyetlerini doğrudan sıfırlar.', 'Piyasaya girişi kolaylaştırır.'], 'Ortak hissedarlar, bir firmanın rakibinden pay kapmasının diğer yatırımlarını zarara uğratacağını bilir; bu durum rekabeti yumuşatma yönünde bir baskı yaratabilir.'),
  ('Rekabet hukukunda pazar payları çok küçük olan firmalar arasındaki anlaşmaların rekabeti önemli ölçüde etkilemeyeceği varsayılarak incelenmemesine ne ad verilir?', 'Önemsizlik (de minimis) kuralı', ['Kendiliğinden yasak kuralı', 'Başarısız firma savunması', 'Temel tesis doktrini'], 'De minimis kuralı, rekabet otoritelerinin kaynaklarını önemli etkisi olan anlaşmalara yöneltmesini sağlar; ağır kartel ihlalleri genellikle bu kapsamın dışında tutulur.'),
  ('Rekabet hukukunda belirli koşulları taşıyan bir anlaşma türünün (ör. dikey anlaşmalar) tek tek incelenmeden topluca yasak kapsamı dışında tutulmasına ne ad verilir?', 'Grup muafiyeti', ['Bireysel muafiyet', 'Pişmanlık programı', 'Uyumlu eylem karinesi'], 'Grup muafiyeti tebliğleri, pazar payı eşiği gibi koşulları sağlayan anlaşmaların otomatik olarak muaf sayılmasını sağlar; bireysel muafiyet ise tek bir anlaşma için verilir.'),
  ('Baskın firma modelinde liderin belirlediği fiyatı veri alarak üretim yapan çok sayıda küçük firmanın oluşturduğu gruba ne ad verilir?', 'Rekabetçi saçak', ['Kartel çekirdeği ve onu izleyen bağımlı üreticiler', 'Stackelberg lideri', 'Monopson grubu'], 'Rekabetçi saçak, baskın firmanın yanında fiyat alıcı gibi davranan küçük üreticilerdir; baskın firma onların arzını talepten düşerek kendi kalan talebini bulur.'),
  ('Rekabet otoritesinin, rekabeti kısıtlayabilecek yasa ve düzenleme taslakları hakkında kamu kurumlarına görüş bildirmesine ne ad verilir?', 'Rekabet savunuculuğu', ['Pişmanlık başvurusu', 'Grup muafiyeti', 'Yerinde inceleme'], 'Rekabet savunuculuğu, piyasaları kamu düzenlemelerinden kaynaklanan gereksiz kısıtlamalardan korumayı amaçlayan, yaptırım dışı bir faaliyettir.'),
  ('John Kenneth Galbraith\'in 1952\'de ortaya attığı \'dengeleyici güç\' kavramı neyi anlatır?', 'Büyük satıcıların gücünün büyük alıcılarca dengelenmesini', ['Devletin bütün fiyatları belirleyerek piyasada kendiliğinden dengeyi kurmasını', 'Küçük firmaların kartel kurmasını', 'Tüketicilerin tekelleri boykot etmesini'], 'Galbraith\'e göre bir taraftaki yoğunlaşma, karşı tarafta da örgütlenmeyi (büyük perakendeciler, sendikalar) doğurur ve piyasa gücü kısmen dengelenir.'),
  ('RPI − X tavan fiyat formülündeki X değeri neyi temsil eder?', 'Firmadan beklenen yıllık verimlilik artışını', ['Firmanın vergi oranını', 'Sektördeki firma sayısını', 'Firmanın sermaye tabanını'], 'Düzenleyici, fiyatların enflasyondan X puan daha az artmasına izin verir; X, firmanın gerçekleştirmesi beklenen verimlilik kazancını yansıtır.'),
  ('Getiri oranı düzenlemesinde firmanın izin verilen toplam kârı nasıl hesaplanır?', 'Sermaye tabanı ile izin verilen getiri oranının çarpımıyla', ['Satış miktarı ile marjinal maliyetin çarpımıyla', 'Çalışan sayısı ile ortalama ücretin çarpımıyla', 'Talep esnekliği ile fiyatın çarpımıyla'], 'Düzenleyici, firmanın yatırdığı sermayeye adil bir getiri oranı uygular; fiyatlar bu kârı ve işletme maliyetlerini karşılayacak düzeyde belirlenir.'),
  ('George Stigler\'in 1971\'de ortaya koyduğu \'düzenleyici kurumun ele geçirilmesi\' kuramı neyi savunur?', 'Düzenleyicilerin zamanla sektörün çıkarlarına hizmet edebileceğini', ['Düzenleyici kurumların her koşulda ve her zaman tüketicileri koruduğunu', 'Düzenlemenin fiyatları her zaman düşürdüğünü', 'Düzenleyici kurumların kaldırılmasının yasak olduğunu'], 'Örgütlü sektörler bilgi, lobi ve kariyer ilişkileri yoluyla düzenlemeyi etkileyebilir; sonuçta düzenleme tüketiciden çok firmaları koruyabilir.'),
  ('Bir doğal tekeli düzenleyen kurumun karşılaştığı temel bilgi sorunu nedir?', 'Firma kendi maliyetlerini düzenleyiciden çok daha iyi bilir.', ['Tüketicilerin talebinin hiç ölçülememesi ve fiyatların gizli kalması', 'Düzenleyicinin firmanın adını bilmemesi', 'Firmanın maliyetlerinin her gün sıfırlanması'], 'Bilgi asimetrisi nedeniyle firma maliyetlerini yüksek göstermeye güdülenebilir; düzenleme tasarımları bu güdüyü sınırlamaya çalışır.'),
  ('Bir kartelin beklenen ek kârı 100 milyon TL\'dir ve kartelin yakalanma olasılığı %20\'dir. Ekonomik caydırıcılık mantığına göre ceza en az kaç TL olmalıdır?', '500 milyon TL', ['100 milyon TL', '20 milyon TL', '120 milyon TL'], 'Beklenen ceza (olasılık × ceza) beklenen kazancı aşmalıdır: 0,20 × C ≥ 100 milyon ⇒ C ≥ 500 milyon TL.'),
  ('Havayolu gibi sabit maliyeti yüksek, ek yolcunun marjinal maliyeti düşük sektörlerde fiyat savaşlarının sert olmasının nedeni nedir?', 'Boş kapasiteyi doldurmak için marjinal maliyete inmek cazip görünür.', ['Bu sektörlerde marjinal maliyet çok yüksek olduğu için fiyatlar kendiliğinden düşer.', 'Bu sektörlerde talep tam inelastiktir.', 'Bu sektörlerde fiyatları devlet belirler.'], 'Düşük marjinal maliyet, ortalama maliyetin çok altına inen fiyatları bile ek koltuk satışı için cazip kılar; rakipler de aynı mantıkla tepki verince fiyatlar sert biçimde düşer.'),
  ('Bir havayolunun indirimli biletlere \'cumartesi gecesini varış noktasında geçirme\' koşulu koymasının amacı nedir?', 'İş yolcularını indirimli bileti almaktan alıkoymak', ['Hafta sonu uçuşlarının maliyetini düşürmek ve yakıt tasarrufu sağlamak', 'Yolcuların daha uzun tatil yapmasını yasal olarak zorunlu kılmak', 'Bilet fiyatlarını herkes için eşitlemek'], 'İş yolcuları genellikle hafta sonunu evde geçirmek ister; bu koşul onları pahalı bilete yönlendiren bir \'çit\' işlevi görür ve fiyata duyarlı tatilcileri ayırır.'),
  ('Dijital ürünlerde (ör. yazılım, e-kitap) ek bir kopyanın maliyetinin sıfıra yakın olması fiyatlama stratejisini nasıl etkiler?', 'Fiyat, ödeme isteğine göre belirlenir ve sürümleme yaygınlaşır.', ['Fiyat her zaman marjinal maliyete, yani sıfıra eşitlenmek zorundadır.', 'Ürün yalnızca tek bir fiyattan satılabilir.', 'Firmalar ürünü hiç satamaz.'], 'Marjinal maliyet fiyat için anlamlı bir alt sınır oluşturmadığından firmalar farklı sürümler ve paketlerle farklı ödeme isteklerine hitap eder; sabit maliyetin karşılanması bu yolla sağlanır.'),
  ('4054 sayılı Kanun\'a göre izne tabi olduğu hâlde Rekabet Kurulu\'nun izni alınmadan gerçekleştirilen bir birleşme için hangisi doğrudur?', 'Hukuken geçerlilik kazanmaz ve taraflara para cezası verilebilir.', ['Kendiliğinden geçerli sayılır ve hiçbir yaptırım uygulanmaz.', 'Yalnızca vergi dairesine bildirilmesi yeterlidir.', 'Birleşen şirketler otomatik olarak kamulaştırılır.'], 'Kanun, izne tabi birleşme ve devralmaların izin alınmadan hukuken geçerlilik kazanmayacağını öngörür; bildirim yapmayan taraflara idari para cezası da uygulanabilir.'),
  ('Rekabet hukukunda birbirinden bağımsız birkaç firmanın birlikte, tek bir varlık gibi pazara hâkim olmasına ne ad verilir?', 'Ortak (kolektif) hâkim durum', ['Tek başına hâkim durum', 'Dikey bütünleşme', 'Barometrik liderlik'], 'Yoğun oligopollerde firmalar aralarındaki ekonomik bağlar ya da piyasa yapısı nedeniyle birlikte hareket edebilir; bu durumda ortak hâkim durumdan söz edilir.'),
  ('4054 sayılı Kanun\'un 6. maddesinde hâkim durumun kötüye kullanılmasına örnek olarak sayılan davranışlardan biri hangisidir?', 'Eşit durumdaki alıcılara farklı koşullar uygulanması', ['Daha verimli üretim yapılması', 'Yeni ürün geliştirilmesi', 'Rakiplerden daha iyi hizmet sunulması'], 'Kanun; eşit durumdakilere ayrımcılık yapılmasını, girişin engellenmesini, bağlama ve arz kısıtlamasını kötüye kullanma örnekleri arasında sayar.'),
  ('İlaç firmalarının patent süresi dolmak üzere olan bir ilaçta küçük değişiklikler yapıp yeni patentler alarak korumayı uzatmasına ne ad verilir?', 'Patent yeşillendirme (evergreening)', ['Zorunlu lisans (kamu yararı gerekçesiyle)', 'Faydalı model başvurusu', 'Paralel ithalat'], 'Önemsiz değişikliklerle patent korumasının uzatılması jenerik rekabeti geciktirir; birçok ülke patent incelemesinde bu uygulamaya karşı önlemler almıştır.'),
  ('Patentli ilaç üreticisinin jenerik üreticiye, ilacın jenerik sürümünü piyasaya sürmeyi ertelemesi karşılığında ödeme yapmasına rekabet hukukunda ne ad verilir?', 'Gecikme için ödeme', ['Yeniden satış fiyatı belirleme', 'Çapraz sübvansiyon', 'Yıkıcı fiyatlama'], 'Bu anlaşmalarda iki taraf tekel kârını paylaşırken tüketiciler ucuz jeneriğe geç ulaşır; ABD ve AB\'de birçok dava konusu olmuştur.'),
  ('Büyük bir firmanın, gelecekte kendi ürününe rakip olabilecek yenilikçi küçük bir girişimi satın alıp geliştirmekte olduğu ürünü rafa kaldırmasına ne ad verilir?', 'Öldürücü satın alma (killer acquisition)', ['Konglomera birleşme (ilgisiz sektörler arası)', 'Ortak girişim', 'Patent havuzu'], 'Bu tür satın almalar potansiyel rekabeti ortadan kaldırır; hedef firmanın cirosu küçük olduğundan geleneksel birleşme eşiklerine takılmayabilir.'),
  ('İş sözleşmelerine konan ve çalışanın işten ayrıldıktan sonra belirli bir süre rakip firmada çalışmasını yasaklayan \'rekabet yasağı\' maddeleri emek piyasasını nasıl etkileyebilir?', 'Çalışanların seçeneklerini azaltıp işverene monopson gücü verir.', ['Çalışanların seçeneklerini artırıp ücretleri kesinlikle yükseltir.', 'Emek piyasasını tam rekabete dönüştürür.', 'İşverenin maliyetini sıfırlar.'], 'Çalışan rakiplere geçemezse işveren ücret pazarlığında güçlenir; bu, rekabetçi düzeyin altında ücret ödenmesine yol açabilir.'),
  ('Rakip işverenlerin birbirlerinin çalışanlarını işe almama konusunda gizlice anlaşması rekabet hukuku açısından nasıl değerlendirilir?', 'Emek piyasasında bir tür alım kartelidir.', ['Meşru bir insan kaynakları politikasıdır ve hiçbir sakıncası yoktur.', 'Yatay birleşmedir.', 'Fiyat farklılaştırmasıdır.'], 'Bu tür \'eleman ayartmama\' anlaşmaları, işverenlerin emek için birbirleriyle rekabet etmesini önler ve ücretleri baskılar; birçok ülkede kartel gibi ele alınır.'),
  ('Bir otomobil tamircisinin gerçekten gerekli olup olmadığını müşterinin kullanımdan sonra bile anlayamayacağı bir parça değişimi önermesi hangi tür malın sorununu gösterir?', 'Güven malı', ['Arama malı', 'Deneyim malı', 'Giffen malı'], 'Güven mallarında (Darby ve Karni, 1973) tüketici kaliteyi ya da gerekliliği satın aldıktan sonra da değerlendiremez; bu durum satıcıya bilgi avantajından doğan bir piyasa gücü verir.'),
  ('Bir hükümetin tam rekabetçi bir sektördeki firmalara birim başına kalıcı sübvansiyon vermesi, sabit maliyetli sektörde uzun dönemde firma sayısını nasıl etkiler?', 'Fiyat düşüp satılan miktar arttığı için firma sayısı artar.', ['Fiyat yükselip satılan miktar azaldığı için firma sayısı azalır.', 'Firma sayısı değişmez; sübvansiyon kârlara eklenir.', 'Tüm firmalar piyasadan çıkar.'], 'Sübvansiyon birim maliyeti düşürür; uzun dönem fiyatı yeni en düşük maliyete iner, talep edilen miktar artar ve bu miktarı daha çok firma karşılar.'),
  ('Buğday gibi tarım ürünlerinin standart kalite sınıflarına ayrılması piyasa yapısını nasıl etkiler?', 'Ürünü homojenleştirip piyasayı tam rekabete yaklaştırır.', ['Ürünü farklılaştırarak her çiftçiyi kendi sınıfının tekeli hâline getirir.', 'Piyasaya girişi yasal olarak yasaklar.', 'Piyasayı oligopole dönüştürür.'], 'Aynı sınıftaki ürünler birbirinin tam ikamesi olur; alıcılar yalnızca fiyata bakar ve tek fiyat oluşur.'),
  ('Fiyat tavanı ile düzenlenen bir doğal tekelin kâr güdüsü nedeniyle hangi alanda tasarrufa gitme riski bulunur?', 'Hizmet kalitesi ve bakım harcamaları', ['Fiyatları tavanın üzerine çıkarma', 'Yeni rakipleri piyasaya davet etme', 'Tüketicilere ücretsiz hizmet verme'], 'Fiyat sabitken maliyeti düşüren her adım kâr getirir; bakım ve kaliteden kısmak da bu yollardan biri olabilir. Bu yüzden tavan fiyat genellikle kalite standartlarıyla birlikte uygulanır.'),
  ('Oyun teorisinde bir bilginin \'ortak bilgi\' olması ne anlama gelir?', 'Herkesin bildiği ve herkesin bunu bildiğinin de bilindiği bilgi', ['Yalnızca bir oyuncunun bildiği ve diğerlerinden sakladığı gizli bilgi', 'Oyunculardan saklanan bilgi', 'Oyunun sonunda açıklanan bilgi'], 'Ortak bilgi varsayımı, oyuncuların birbirlerinin akıl yürütmelerini öngörebilmesinin temelidir; geriye doğru tümevarım gibi yöntemler buna dayanır.'),
  ('Bir hükümetin yerli üreticinin tek olduğu bir sektörde ithalata kota koyması, yerli üreticinin fiyatlama davranışını nasıl etkiler?', 'Dış rekabet sınırlandığı için fiyatı daha da yükseltebilir.', ['Fiyatı dünya fiyatının altına indirmek zorunda kalır.', 'Hiçbir biçimde etkilenmez.', 'Piyasadan çıkmak zorunda kalır.'], 'Kota, ithalatla gelebilecek rekabet baskısını belirli bir miktarla sınırlar; yerli tekel kalan talep üzerinde daha fazla fiyat gücü kullanabilir.'),
];
